const GAME={title:{nl:"Fluisteringen van Ravenholt — Deel 2",en:"Whispers of Ravenholt — Part 2"},titleLines:{nl:["Fluisteringen","van Ravenholt","· Deel 2 ·"],en:["Whispers of","Ravenholt","· Part 2 ·"]},startScene:"courtyard",assetVer:"209",sprites:{hero:"assets/art/hero.webp",heroIdle2:"assets/art/hero-idle2.webp",heroBlink:"assets/art/hero-blink.webp",heroBlink2:"assets/art/hero-blink2.webp",heroWalk:"assets/art/hero-walk.webp",heroWalk2:"assets/art/hero-walk2.webp",heroWave:"assets/art/hero-wave.webp",heroWave2:"assets/art/hero-wave2.webp",heroWalkSheet:"assets/art/hero-walk-sheet.webp",ravenPerch:"assets/art/raven-perch.png",ravenFly:"assets/art/raven-fly.png",ravenFlyUp:"assets/art/raven-fly-up.webp",ravenFlyMid:"assets/art/raven-fly-mid.png",ravenFlyDown:"assets/art/raven-fly-down.png",heroWalkDiag:"assets/art/hero-walk-diag.webp",dragonShadow:"assets/art/dragon-shadow.webp",squire:"assets/art/squire.png",princess:"assets/art/princess.png",parrot:"assets/art/parrot.webp",librarian:"assets/art/librarian.webp","librarian-sleep":"assets/art/librarian-sleep.webp",dungeonGuard:"assets/art/dungeon-guard.webp",father:"assets/art/father.webp"},heroWalkFrames:16,spriteDetail:2,startItems:["spellbook","spell","dragonspell"],startFlags:["mapFiled","spellWritten","gotRecipe","dragonSpellLearned"],winText:{nl:"Gefeliciteerd — je hebt Whispers of Ravenholt Deel 2 uitgespeeld! Je leerde twee nieuwe spreuken, verduisterde de zon, sloop onzichtbaar langs de wachter en leidde hem af met een dansend plantje. Je vader is VRIJ! Samen lopen jullie de trap op, het daglicht tegemoet. Knap gedaan, held!",en:"Congratulations — you beat Whispers of Ravenholt Part 2! You learned two new spells, darkened the sun, slipped past the guard unseen and distracted him with a dancing little plant. Your father is FREE! Together you climb the stairs toward the daylight. Well done, hero!"},strings:{noEffect:{nl:"Dat werkt hier niet.",en:"That doesn’t work here."},noCombine:{nl:"Die twee laten zich niet combineren.",en:"Those two don’t combine."},nothingThere:{nl:"Daar valt niets te ontdekken.",en:"There’s nothing to find there."}},ui:{subtitle:{nl:"Deel 2 — Het Kasteel van Eldoria",en:"Part 2 — The Castle of Eldoria"},intro:{nl:"Het verhaal tot nu toe: in Deel 1 bracht Finn het water terug naar Ravenholt en leerde hij de dans-spreuk en de drakenspreuk. Nu is hij het kasteel van Eldoria binnengeglipt, want daar zit zijn vader gevangen.",en:"The story so far: in Part 1, Finn brought the water back to Ravenholt and learned the dance spell and the dragon spell. Now he has slipped into the castle of Eldoria, where his father is held captive."},credit:{nl:"Een RetroAdventureWorld-avontuur",en:"A RetroAdventureWorld adventure"},startBtn:{nl:"Begin het mysterie",en:"Begin the mystery"},winTitle:{nl:"Deel 2 uitgespeeld!",en:"Part 2 complete!"},replayBtn:{nl:"Opnieuw spelen",en:"Play again"},playOther:{nl:"▸ Speel een ander avontuur",en:"▸ Play another adventure"},deathTitle:{nl:"Verloren in de mist...",en:"Lost in the fog..."},deathText:{nl:"Dat liep niet goed af. Probeer het opnieuw.",en:"That went badly. Try again."},retryBtn:{nl:"Probeer opnieuw",en:"Try again"},rotateTitle:{nl:"Draai je telefoon",en:"Rotate your phone"},rotateText:{nl:"Dit avontuur speelt liggend. Draai je scherm een kwartslag.",en:"This adventure plays in landscape. Turn your screen sideways."},tapContinue:{nl:"tik om verder te gaan ▸",en:"tap to continue ▸"},selected:{nl:"geselecteerd",en:"selected"},homeConfirm:{nl:"Terug naar RetroAdventureWorld? Je voortgang wordt bewaard.",en:"Back to RetroAdventureWorld? Your progress is saved."},continueBtn:{nl:"Verder spelen",en:"Continue"},skipBtn:{nl:"Overslaan ▸",en:"Skip ▸"},hintBtn:{nl:"💡 Hint",en:"💡 Hint"},eclTipBtn:{nl:"💡 Geef me een hint",en:"💡 Give me a hint"},leverBtn:{nl:"TREK AAN DE HENDEL",en:"PULL THE LEVER"},eclOuter:{nl:"buitenste",en:"outer"},eclMiddle:{nl:"middelste",en:"middle"},eclInner:{nl:"binnenste",en:"inner"},eclTurns:{nl:"draait",en:"turns"},eclOuterBack:{nl:"Buitenring terug",en:"Outer ring back"},eclOuterFwd:{nl:"Buitenring vooruit",en:"Outer ring forward"},eclMidBack:{nl:"Middenring terug",en:"Middle ring back"},eclMidFwd:{nl:"Middenring vooruit",en:"Middle ring forward"},eclInBack:{nl:"Binnenring terug",en:"Inner ring back"},eclInFwd:{nl:"Binnenring vooruit",en:"Inner ring forward"},close:{nl:"Sluiten",en:"Close"},sound:{nl:"Geluid aan of uit",en:"Sound on or off"},home:{nl:"Terug naar RetroAdventureWorld",en:"Back to RetroAdventureWorld"},winHome:{nl:"Naar home",en:"Home"},inventory:{nl:"Inventaris",en:"Inventory"},saveGame:{nl:"Spel opslaan",en:"Save game"},showTip:{nl:"Toon de tip",en:"Show the hint"},showSpots:{nl:"Toon waar je kunt tikken",en:"Show what you can tap"},switchLang:{nl:"Wissel taal (English)",en:"Switch language (Nederlands)"},prevPage:{nl:"Vorige bladzijde",en:"Previous page"},nextPage:{nl:"Volgende bladzijde",en:"Next page"},hold:{nl:"✋ Vasthouden",en:"✋ Hold"},lower:{nl:"⟳ Laten zakken",en:"⟳ Lower"},q_explore:{nl:"Verken de binnenplaats van het kasteel — en zoek de weg naar de slottuin",en:"Explore the castle courtyard — and find the way to the garden"},q_getsword:{nl:"De schildknaap gaf je het gebroken zwaard van Sir Aldric. Smeed het weer heel bij de smidse: je hebt de hamer en houtskool nodig. De hamer zit in het smidsbeeld in de tuin — dat vraagt de geheime woorden van de smid. Geef de papagaai de pinda (ligt op het plein) en hij verklapt ze.",en:"The squire gave you Sir Aldric’s broken sword. Forge it whole at the smithy: you need the hammer and charcoal. The hammer is in the smith statue in the garden — it asks for the smith’s secret words. Give the parrot the peanut (it lies in the courtyard) and he’ll reveal them."},q_gethammer:{nl:"Voor de hamer: bij het smidsbeeld in de tuin moet je de geheime woorden van de smid aantikken. Geef de papagaai de pinda (bij het aambeeld op het plein) — hij verklapt welke woorden, en in welke volgorde",en:"For the hammer: at the smith statue in the garden you must tap the smith’s secret words. Give the parrot the peanut (by the anvil in the courtyard) — he reveals which words, and in what order"},q_giveparrot:{nl:"Je hebt een pinda — geef hem aan de papagaai in de slottuin; hij verklapt de geheime woorden van de smid",en:"You have a peanut — give it to the parrot in the garden; he reveals the smith’s secret words"},q_typephrase:{nl:"De papagaai verklapte de spreuk van de smid: ONLY · FIRE · FORGES · TRUE · STEEL (Engels voor “alleen vuur smeedt echt staal”). Tik die woorden in díe volgorde aan bij het smidsbeeld in de tuin om de hamer te krijgen",en:"The parrot revealed the smith’s saying: ONLY · FIRE · FORGES · TRUE · STEEL. Tap those words in that order at the smith statue in the garden to get the hammer"},q_getcoal:{nl:"Schep houtskool uit de rechter vuurkorf naast het smidsbeeld in de slottuin om het smidsvuur mee aan te wakkeren",en:"Scoop charcoal from the right fire basket beside the smith statue in the garden to kindle the forge fire"},q_forge:{nl:"Smeed bij de smidse: gooi eerst de houtskool in de oven (het vuur laait fel op), leg dán het gebroken zwaard op het ijzer, en sla het ten slotte met de hamer weer heel",en:"Forge at the smithy: first throw the charcoal into the oven (the fire flares up), then lay the broken sword on the iron, and finally strike it whole with the hammer"},q_takesword:{nl:"Het zwaard is weer heel! Het ligt te glanzen bij de markttent rechts — pak het op",en:"The sword is whole again! It gleams by the market tent on the right — go and take it"},q_getrope:{nl:"Het zwaard is gesmeed! Praat met de schildknaap — nu geeft hij je het touw dat je bij de put nodig hebt",en:"The sword is forged! Talk to the squire — now he’ll give you the rope you need at the well"},q_getcoin:{nl:"Voor de put heb je hulp van de raaf nodig. Vis eerst de glinsterende bronzen munt uit de leeuwenfontein in de tuin (tik op het bekken, niet op de leeuwenkop)",en:"For the well you need the raven’s help. First fish the gleaming bronze coin from the lion fountain in the garden (tap the basin, not the lion’s head)"},q_giveraven:{nl:"Geef de bronzen munt aan de glanzende raaf op de put — hij springt er dan mee de emmer in, de diepte in",en:"Give the bronze coin to the glossy raven on the well — he’ll hop into the bucket with it and dive down"},q_haulwell:{nl:"De raaf zit met de ketting in de emmer onderin de put. Gebruik het touw (van de schildknaap) op het windwerk om de emmer omhoog te hijsen",en:"The raven sits with the necklace in the bucket deep in the well. Use the rope (from the squire) on the winch to haul the bucket up"},q_givenecklace:{nl:"Je viste de ketting van de prinses op — breng hem naar de prinses in de slottuin",en:"You fished up the princess’s necklace — bring it to the princess in the garden"},q_fountainpuzzle:{nl:"Je kreeg een sleutel van de prinses — los de schuifpuzzel bij de leeuwenfontein op om het slot te onthullen",en:"The princess gave you a key — solve the sliding puzzle at the lion fountain to reveal the lock"},q_usekey:{nl:"Gebruik de sleutel op het sleutelgat in de muur naast de leeuwenfontein om de geheime poort te openen",en:"Use the key on the keyhole in the wall beside the lion fountain to open the secret gate"},q_library:{nl:"Door de geheime poort kom je in de kasteelbibliotheek. Een oude tovenaar bewaakt het gloeiende boek — leg de gloeizwammen (van de put) in de schaal met kaarsen náást hem; van de rook wordt hij slaperig",en:"Through the secret gate you reach the castle library. An old wizard guards the glowing book — lay the glow-caps (from the well) in the bowl of candles beside him; the smoke will make him sleepy"},q_takespell:{nl:"De tovenaar is staand in slaap gesukkeld — bekijk het ZONNESTELSEL op de sokkel rechts en draai de hemelschijf: daar wacht de Zonsverduistering-spreuk",en:"The wizard has dozed off on his feet — examine the SOLAR SYSTEM on the pedestal to the right and turn the celestial disc: the Solar Eclipse spell awaits"},q_castEclipse:{nl:"Je hebt de Zonsverduistering-spreuk! Tik hem aan in je tas en spreek hem uit bij het grote raam van de bibliotheek",en:"You have the Solar Eclipse spell! Tap it in your bag and speak it at the great library window"},q_readbook:{nl:"De zon is verduisterd — het gloeiende boek is nu te LEZEN! Tik het aan en ontvang de SPREUK VAN ONZICHTBAARHEID",en:"The sun is eclipsed — the glowing book can be READ now! Tap it and receive the SPELL OF INVISIBILITY"},q_altar:{nl:"De onzichtbaarheidsspreuk is binnen! Open nu de geheime deur: kijk tijdens de ZONSVERDUISTERING door de telescoop naar de hemelschijf van de Raaf, en draai de schijven van het DEURZEGEL tot die drie tekens bovenaan staan (1 = buitenste, 2 = middelste, 3 = binnenste). Trek dan aan de hendel",en:"The invisibility spell is yours! Now open the secret door: during the ECLIPSE, look through the telescope at the Raven’s sky-wheel, then turn the DOOR SEAL discs until those three signs sit at the top (1 = outer, 2 = middle, 3 = inner). Then pull the lever"},q_dungeon:{nl:"De geheime deur staat open! Daal de trap af naar de kerker. Een wachter verspert de weg naar de gevangene — tik de onzichtbaarheidsspreuk aan om ongezien langs hem te sluipen",en:"The secret door is open! Descend the stair to the dungeon. A guard blocks the way to the prisoner — tap the invisibility spell to slip past him unseen"},q_key:{nl:"Je bent onzichtbaar langs de wachter! Pak nu MUISSTIL de gouden sleutel van de wachttafel: schuif de stippen-sleutels één voor één opzij (•, ••, •••) en pauzeer zodat de geluidsmeter niet volloopt",en:"You slipped past the guard unseen! Now take the golden key from the guard’s table SILENTLY: slide the dotted keys aside one by one (•, ••, •••) and pause so the noise meter doesn’t fill up"},q_distract:{nl:"Je hebt de gouden sleutel! Maar de wachter staart recht naar de cel... Vraag je VADER om raad",en:"You have the golden key! But the guard stares straight at the cell... Ask your FATHER for advice"},q_throwNut:{nl:"Vader gaf je een WONDERNOOT! Gooi hem in het plasje water links bij de trap",en:"Father gave you a WONDER-NUT! Toss it into the puddle of water by the stairs, on the left"},q_dance:{nl:"De wondernoot dobbert in het plasje... Spreek nu de DANS-SPREUK uit (tik hem aan in je tas) en kijk wat er groeit!",en:"The wonder-nut bobs in the puddle... Now cast the DANCE SPELL (tap it in your bag) and watch what grows!"},q_cellopen:{nl:"De wachter kijkt de andere kant op — gebruik de celsleutel NU op de celdeur en bevrijd je vader!",en:"The guard looks the other way — use the cell key on the cell door NOW and free your father!"}},items:{staff:{name:{nl:"Vaders Staf",en:"Father’s Staff"},icon:"🪄",img:"assets/art/item-staff.png",look:{nl:"De houten staf van mijn vader. Hij voelt vertrouwd in je hand — met de juiste spreuk in je boek kun je hem laten werken.",en:"My father’s wooden staff. It feels familiar in your hand — with the right spell in your book you can make it work."}},invisspell:{name:{nl:"Onzichtbaarheidsspreuk",en:"Invisibility Spell"},icon:"👻",img:"assets/art/item-invisspell.webp",sparkle:!0,border:"blue",look:{nl:"De onzichtbaarheidsspreuk uit het gloeiende boek — gelezen bij het licht van de zonsverduistering. De letters lijken weg te vagen terwijl je kijkt... Spreek hem uit waar een bewaker je níet mag zien. (Tik de spreuk aan om hem uit te spreken.)",en:"The invisibility spell from the glowing book — read by the light of the solar eclipse. Its letters seem to fade away as you watch... Speak it where a guard must not see you. (Tap the spell to cast it.)"}},eclipsspell:{name:{nl:"Zonsverduistering-spreuk",en:"Solar Eclipse Spell"},icon:"🌑",img:"assets/art/item-eclipsspell.png",border:"blue",look:{nl:"De Spreuk van de Zonsverduistering — “Umbra Solis” — uit het koperen zonnestelsel in de bibliotheek. Spreek hem uit bij het grote raam van de bibliotheek en de zon dooft, zodat de sterren zich overdag tonen. (Tik de spreuk aan om hem uit te spreken.)",en:"The Spell of the Solar Eclipse — “Umbra Solis” — from the brass solar system in the library. Speak it at the great library window and the sun goes dark, so the stars show themselves by day. (Tap the spell to cast it.)"}},hammer:{name:{nl:"Smidshamer",en:"Blacksmith’s Hammer"},icon:"🔨",img:"assets/art/item-hammer.png",look:{nl:"Een zware smidshamer uit de sokkel van het smidsbeeld in de slottuin. Hiermee kun je bij de smidse het zwaard van de held smeden.",en:"A heavy blacksmith’s hammer from the plinth of the smith statue in the castle garden. With it you can forge the hero’s sword at the smithy."}},swordBroken:{name:{nl:"Gebroken Zwaard",en:"Broken Sword"},icon:"🗡️",img:"assets/art/item-sword-broken.png",look:{nl:"Het zwaard van Sir Aldric, doormidden gebroken — het losse stuk zit er nog bij. Bij een heet smidsvuur en met een hamer zou je het weer heel kunnen smeden.",en:"Sir Aldric’s sword, snapped in two — the broken-off piece is still with it. At a hot forge fire and with a hammer you could make it whole again."}},rope:{name:{nl:"Touw",en:"Rope"},icon:"🪢",img:"assets/art/item-rope.png",look:{nl:"Een stevig opgerold touw van de schildknaap. Lang genoeg om iets uit een diepe put omhoog te vissen.",en:"A sturdy coil of rope from the squire. Long enough to fish something up from a deep well."}},necklace:{name:{nl:"Ketting van de Prinses",en:"The Princess’s Necklace"},icon:"📿",img:"assets/art/item-necklace.png",sparkle:!0,border:"gold",look:{nl:"Een fijne gouden ketting met een blauwe edelsteen, opgevist uit de oude put. Hij hoort bij de prinses — het was van haar moeder.",en:"A fine gold necklace with a blue gem, fished from the old well. It belongs to the princess — it was her mother’s."}},key:{name:{nl:"Sleutel van de Geheime Poort",en:"Secret Gate Key"},icon:"🗝️",img:"assets/art/item-key.png",sparkle:!0,look:{nl:"Een zware, oude sleutel die je van de prinses kreeg. Hij past op het verborgen slot in de muur naast de leeuwenfontein — de geheime poort.",en:"A heavy old key the princess gave you. It fits the hidden lock in the wall beside the lion fountain — the secret gate."}},cellkey:{name:{nl:"Gouden Celsleutel",en:"Golden Cell Key"},icon:"🗝️",img:"assets/art/item-cellkey.png",sparkle:!0,border:"gold",look:{nl:"De gouden sleutel van de wachter — muisstil van de bos bevrijd. Hij past op het glinsterende sleutelslot van de celdeur.",en:"The guard’s golden key — freed from the ring without a sound. It fits the glittering keyhole of the cell door."}},charcoal:{name:{nl:"Houtskool",en:"Charcoal"},icon:"⬛",img:"assets/art/item-coal.png",look:{nl:"Een handvol zwarte houtskool uit de vuurkorf naast het smidsbeeld in de slottuin. Precies wat een smid nodig heeft om zijn vuur weer aan te wakkeren.",en:"A handful of black charcoal from the fire basket beside the smith statue in the castle garden. Just what a smith needs to fire up his forge again."}},bignut:{name:{nl:"Wondernoot",en:"Wonder-Nut"},icon:"🌰",img:"assets/art/item-bignut.webp",sparkle:!0,look:{nl:"Een grote glanzende noot van je vader. Er zit al een piepklein groen scheutje in — hier wil een plant uit groeien! Hij heeft alleen water nodig... en misschien een dansje.",en:"A big glossy nut from your father. A tiny green sprout already peeks out — a plant wants to grow from this! It only needs water... and perhaps a little dance."}},nut:{name:{nl:"Pinda",en:"Peanut"},icon:"🥜",img:"assets/art/item-nut.png",look:{nl:"Een pinda, half uit de dop — hij lag bij het aambeeld van de smidse. Vogels — papagaaien zeker — zijn er dol op.",en:"A peanut, half broken out of its shell — it lay by the smithy anvil. Birds — parrots especially — love these."}},trinket:{name:{nl:"Bronzen Munt",en:"Bronze Coin"},icon:"🪙",img:"assets/art/item-trinket.png",sparkle:!0,look:{nl:"Een glanzende bronzen munt die je uit de leeuwenfontein opviste. Hij blinkt schitterend in het licht — precies het soort glimmend ding waar een raaf geen weerstand aan kan bieden.",en:"A gleaming bronze coin you fished from the lion fountain. It shines brilliantly in the light — exactly the kind of bright thing a raven cannot resist."}},mushroom:{name:{nl:"Gloeizwammen",en:"Glow-caps"},icon:"🍄",img:"assets/art/item-mushroom.webp",sparkle:!0,look:{nl:"Een trosje gloeizwammen: paddenstoelen met zacht oplichtende blauw-paarse hoedjes, geplukt bij de put. Wie hun rook opsnuift, wordt heel erg slaperig.",en:"A little bunch of glow-caps: mushrooms with softly glowing blue-purple tops, picked by the well. Anyone who sniffs their smoke gets very, very sleepy."}},sword:{name:{nl:"Zwaard van Sir Aldric",en:"Sir Aldric’s Sword"},icon:"⚔️",img:"assets/art/item-sword.png",sparkle:!0,border:"gold",look:{nl:"Het zwaard van Sir Aldric, dat je zelf bij de smidse weer heel hebt gesmeed. Het lemmet glanst als nieuw — een waardig wapen voor een held.",en:"Sir Aldric’s sword, which you forged whole again yourself at the smithy. The blade gleams like new — a weapon worthy of a hero."}},spellbook:{name:{nl:"Toverboek",en:"Spellbook"},icon:"📕",sparkle:e=>(e.flags.gotEclipseSpell?1:0)+(e.flags.gotInvisSpell?1:0)>(e.flags.bookNewSpellsSeen||0),img:e=>e.flags.spellWritten?"assets/art/item-spellbook.png":"assets/art/item-spellbook-plain.png",zoomImg:e=>e.flags.dragonSpellLearned?"assets/art/spell-dragon.webp":"assets/art/spell-dance.webp",zoomImgFlag:"spellWritten",look:e=>e.flags.spellWritten?{nl:"Je toverboek, met de bladzijden uit Deel 1 en elke nieuwe spreuk die je hier leert. (tik aan om te bladeren)",en:"Your spellbook, with the pages from Part 1 and every new spell you learn here. (tap to leaf through it)"}:{nl:"Het oude toverboek — de bladzijden zijn nog helemaal leeg. Je moet de spreuken er nog zelf in schrijven, met een magische veer gedoopt in bessensap. (maak inkt van zwarte bessen, doop de ravenveer erin en combineer die met dit boek)",en:"The old spellbook — its pages are still completely blank. You must still write the spells in yourself, with a magic feather dipped in berry juice. (make ink from black berries, dip the raven feather in it and combine it with this book)"}},spell:{name:{nl:"Dans-spreuk",en:"Dance Spell"},icon:"✦",img:"assets/art/item-spell.png",border:"blue",look:{nl:"De spreuk die je zelf in het toverboek schreef, gloeit zacht blauw na. Hiermee laat je dingen dansen. (Tik de spreuk aan om hem uit te spreken.)",en:"The spell you wrote yourself in the spellbook glows softly blue. With it you can make things dance. (Tap the spell to cast it.)"}},dragonspell:{name:{nl:"Drakenspreuk",en:"Dragon Spell"},icon:"🐉",img:"assets/art/item-dragonspell.png",border:"blue",look:{nl:"De drakenspreuk “Draconis Umbra” die zich in je toverboek schreef. Spreek hem uit en er rijst een enorme drakenschaduw op — genoeg om de dapperste wachter te laten schrikken.",en:"The dragon spell “Draconis Umbra” that wrote itself into your spellbook. Speak it and a huge dragon shadow rises — enough to startle the bravest guard."}}},recipes:[],questRules:[{when:{has:"cellkey",flag:"guardTurned",notFlag:"fatherFreed"},quest:"q_cellopen"},{when:{flag:"nutInPuddle",notFlag:"guardTurned"},quest:"q_dance"},{when:{flag:"gotNut",notFlag:"nutInPuddle"},quest:"q_throwNut"},{when:{has:"cellkey",notFlag:"guardTurned"},quest:"q_distract"},{when:{flag:"guardPassed",notFlag:"gotCellKey"},quest:"q_key"},{when:{flag:"altarSolved",notFlag:"fatherFreed"},quest:"q_dungeon"},{when:{flag:"sawSigns",notFlag:"altarSolved"},quest:"q_altar"},{when:{flag:"eclipseActive",notFlag:"sawSigns"},quest:"q_readbook"},{when:{flag:"gotEclipseSpell",notFlag:"eclipseActive"},quest:"q_castEclipse"},{when:{flag:"wizardTripping",notFlag:"gotEclipseSpell"},quest:"q_takespell"},{when:{flag:"secretGateOpen",notFlag:"gotInvisSpell"},quest:"q_library"},{when:{has:"key",flag:"fountainSolved"},quest:"q_usekey"},{when:{has:"key"},quest:"q_fountainpuzzle"},{when:{has:"necklace"},quest:"q_givenecklace"},{when:{has:"rope",flag:"ravenInBucket",notFlag:"gotNecklace"},quest:"q_haulwell"},{when:{flag:"ravenInBucket",notFlag:"gotNecklace"},quest:"q_haulwell"},{when:{has:"trinket"},quest:"q_giveraven"},{when:{flag:"gotSword",notFlag:"squireGaveRope"},quest:"q_getrope"},{when:{flag:"gotSword",notFlag:"gotNecklace"},quest:"q_getcoin"},{when:{flag:"swordForged",notFlag:"gotSword"},quest:"q_takesword"},{when:{flag:"swordInForge",notFlag:"gotSword"},quest:"q_forge"},{when:{has:["swordBroken","hammer","charcoal"],notFlag:"gotSword"},quest:"q_forge"},{when:{has:["swordBroken","hammer"],notFlag:"gotSword"},quest:"q_getcoal"},{when:{flag:"gotSmithPhrase",notFlag:"statuePuzzleSolved"},quest:"q_typephrase"},{when:{has:"nut",notFlag:"gotSmithPhrase"},quest:"q_giveparrot"},{when:{has:["swordBroken","charcoal"],notFlag:"gotSword"},quest:"q_gethammer"},{when:{has:"swordBroken",notFlag:"gotSword"},quest:"q_getsword"},{when:{flag:"metSquire",notFlag:"gotSword"},quest:"q_getsword"},{when:{has:"rope"},quest:"q_getcoin"},{when:{},quest:"q_explore"}],scenes:{courtyard:{name:{nl:"De Binnenplaats",en:"The Courtyard"},bg:"assets/art/scene-courtyard.webp",bgVariants:[{img:"assets/art/scene-courtyard-raven-sword.webp",flags:["ravenInBucket","squireGaveRope"],notFlags:["gotNecklace"]},{img:"assets/art/scene-courtyard-raven-sword.webp",flags:["ravenInBucket","swordForged"],notFlags:["gotNecklace","gotSword"]},{img:"assets/art/scene-courtyard-raven-swordgone.webp",flags:["ravenInBucket","squireGaveSword"],notFlags:["gotNecklace"]},{img:"assets/art/scene-courtyard-raven.webp",flags:["ravenInBucket"],notFlags:["gotNecklace"]},{img:"assets/art/scene-courtyard-sword.webp",flags:["squireGaveRope"]},{img:"assets/art/scene-courtyard-sword.webp",flags:["swordForged"],notFlags:["gotSword"]},{img:"assets/art/scene-courtyard-swordgone.webp",flags:["squireGaveSword"]}],charFilter:"saturate(1.07) brightness(1.01) sepia(0.17) contrast(1.03)",heroShade:.95,entryText:{nl:"De binnenplaats van het kasteel van Eldoria baadt in het late ochtendlicht. Midden op de keien staat een oude put met een houten dakje. Links gloeit de smidse na en leidt een begroeide boog naar de slottuin; rechts staat een markttent bij de grote kasteeldeur. Op de put zit een glanzende zwarte raaf.",en:"The courtyard of Eldoria castle bathes in late morning light. In the middle of the cobbles stands an old well with a wooden roof. To the left the forge glows and an ivy-clad arch leads to the castle garden; to the right a market tent stands by the great castle door. A glossy black raven perches on the well."},playerStart:{x:300,y:296},spawnFrom:{garden:{x:178,y:252}},depth:{far:205,near:316,sFar:.72,sNear:1.05},walkable:[{x:24,y:252,w:520,h:62},{x:24,y:212,w:184,h:46},{x:356,y:208,w:188,h:50}],obstacles:[{x:224,y:166,w:122,h:84},{x:0,y:200,w:140,h:50},{x:0,y:250,w:62,h:64},{x:455,y:208,w:113,h:106}],overlays:[],fx:{forgeFlame:{flag:"ovenStoked",x:37,y:199,h:9,fade:.6}},worldItems:[{item:"nut",hotspot:"nut",x:116,y:252,scale:.66,filter:"brightness(0.5)"},{item:"mushroom",hotspot:"mushroom",x:230,y:222,scale:.82,glowCol:"150,110,240"}],npcs:[{id:"squire",sprite:"squire",sway:!0,filter:"brightness(0.78) saturate(0.92)",x:486,y:284,scale:1.18,flip:!0},{id:"courtyardRaven",sprite:"ravenPerch",x:292,y:95,scale:.95,flip:!1,peck:!0,peckAmt:.4,hideFlag:"ravenInBucket"}],hotspots:[{id:"squire",name:{nl:"De Schildknaap",en:"The Squire"},face:"assets/art/face-squire.png",rect:{x:456,y:184,w:70,h:104},walkTo:{x:452,y:300},look:e=>e.flags.squireGaveRope?{nl:"De schildknaap knikt naar het zwaard aan je zij. “Je hebt het zwaard van Sir Aldric weer heel gesmeed — knap werk. Met dat touw bereik je wat in de oude put verloren ging.”",en:"The squire nods at the sword at your side. “You forged Sir Aldric’s sword whole again — fine work. With that rope you can reach what was lost in the old well.”"}:e.flags.gotSword?{nl:"De schildknaap glundert om het herstelde zwaard. “Prachtig gesmeed! Hier — een stevig touw. Dat heb je vast nodig bij de oude put.”",en:"The squire beams at the reforged sword. “Beautifully forged! Here — a sturdy rope. You’ll want it at the old well.”"}:e.flags.swordForged?{nl:"De schildknaap wijst trots naar de markttent. “Het zwaard van Sir Aldric — weer heel! Pak het gerust, het is van jou.”",en:"The squire points proudly at the market tent. “Sir Aldric’s sword — whole again! Take it, it’s yours.”"}:e.flags.squireGaveSword?{nl:"De schildknaap wijst naar de smidse. “Smeed het zwaard van de held: gooi eerst houtskool in de oven zodat het vuur hoog oplaait, leg dán het gebroken zwaard op het ijzer, en sla het met de hamer weer heel. De hamer zit verborgen in de sokkel van het smidsbeeld in de slottuin; houtskool vind je in de vuurkorf ernaast.”",en:"The squire points at the smithy. “Forge the hero’s sword: first throw charcoal in the oven so the fire roars up, then lay the broken sword on the iron, and strike it whole with the hammer. The hammer is hidden in the plinth of the smith statue in the garden; you will find charcoal in the fire basket beside it.”"}:{nl:"Een jonge schildknaap in een blauw wapenkleed houdt de wacht bij de koude smidse. Hij knikt je vriendelijk toe. “De koning ontvangt niemand meer, niet sinds de oude held viel — Sir Aldric, de Leeuw van Eldoria, de grootvader van de prinses. Zijn zwaard brak in tweeën en het hele kasteel verstomde van rouw.” Hij overhandigt je de twee stukken van het gebroken zwaard. “Smeed het bij de smidse weer heel — jij bent er klaar voor. Als het zwaard klaar is, krijg je van mij een touw.”",en:"A young squire in a blue tabard keeps watch by the cold smithy. He gives you a friendly nod. “The king sees no one anymore, not since the old hero fell — Sir Aldric, the Lion of Eldoria, the princess’s grandfather. His sword broke in two and the whole castle fell silent with grief.” He hands you the two pieces of the broken sword. “Forge it whole at the smithy — you’re ready for it. Once the sword is done, I’ll give you a rope.”"},givesWhen:[{setFlag:["metSquire","squireGaveSword"],item:"swordBroken",giveText:{nl:"De jonge schildknaap knikt je toe. “De koning ontvangt niemand meer, niet sinds de oude held viel — Sir Aldric, de Leeuw van Eldoria. Zijn zwaard brak in tweeën en het hele kasteel verstomde van rouw.” Hij legt meteen het gebroken zwaard — beide stukken — in je handen. “Smeed het weer heel bij de smidse: houtskool in de oven, het zwaard op het ijzer, en dan de hamer. Als het klaar is, krijg je van mij een touw. Veel succes, vriend.”",en:"The young squire nods at you. “The king sees no one anymore, not since the old hero fell — Sir Aldric, the Lion of Eldoria. His sword broke in two and the whole castle fell silent with grief.” He places the broken sword — both pieces — into your hands at once. “Forge it whole at the smithy: charcoal in the oven, the sword on the iron, then the hammer. Once it’s done, I’ll give you a rope. Good luck, friend.”"}},{flag:"gotSword",setFlag:"squireGaveRope",item:"rope",consume:"sword",giveText:{nl:"De schildknaap neemt het herstelde zwaard van Sir Aldric eerbiedig van je aan. “Sir Aldric zou trots zijn — ik bewaar het veilig. Zoals beloofd: hier is het touw. Daarmee bereik je wat in de oude put verloren ging.”",en:"The squire reverently takes Sir Aldric’s reforged sword from you. “Sir Aldric would be proud — I’ll keep it safe. As promised: here is the rope. With it you can reach what was lost in the old well.”"}}],setFlag:"metSquire"},{id:"takesword",name:{nl:"Het Gesmede Zwaard",en:"The Forged Sword"},rect:{x:440,y:184,w:50,h:64},walkTo:{x:436,y:300},appearFlag:"swordForged",hideFlag:"gotSword",look:{nl:"Het weer hele zwaard van Sir Aldric staat te glanzen tegen de markttent. Pak het op!",en:"Sir Aldric’s reforged sword gleams against the market tent. Take it!"},givesWhen:{flag:"swordForged",setFlag:"gotSword",item:"sword",giveText:{nl:"Je pakt het weer hele zwaard van Sir Aldric op. Het lemmet glanst als nieuw en ligt perfect in je hand — een waardig wapen voor een held.",en:"You take up Sir Aldric’s reforged sword. The blade gleams like new and sits perfectly in your hand — a weapon worthy of a hero."}}},{id:"well",name:{nl:"De Oude Put",en:"The Old Well"},rect:{x:224,y:150,w:120,h:108},walkTo:{x:286,y:300},look:e=>e.flags.gotNecklace?{nl:"De oude put. Diep beneden klatert het donkere water. De ketting van de prinses heb je veilig omhoog gehesen.",en:"The old well. Far below, dark water trickles. You’ve safely hauled up the princess’s necklace."}:e.flags.ravenInBucket?{nl:"De raaf zit parmantig in de emmer, klaar voor de afdaling. Diep beneden glinstert iets in het donkere water. Laat de emmer voorzichtig zakken — maar het windwerk heeft eerst een touw nodig.",en:"The raven perches proudly in the bucket, ready for the descent. Deep below, something glints in the dark water. Lower the bucket carefully — but the winch needs a rope first."}:{nl:"Een oude stenen put met een houten windwerk, maar zonder touw. Diep beneden, in het donkere water, ligt iets te glinsteren — te diep om er zelf bij te komen. Misschien kan iets (of iemand) kleins het halen?",en:"An old stone well with a wooden winch, but no rope. Far below, in the dark water, something glints — too deep to reach yourself. Maybe something (or someone) small could fetch it?"},dialPuzzle:{requiresFlag:"ravenInBucket",blockedText:{nl:"De put is veel te diep om er zelf bij te komen. Lok eerst de raaf de emmer in met iets glimmends.",en:"The well is far too deep to reach yourself. First lure the raven into the bucket with something shiny."},needItem:"rope",needText:{nl:"Het windwerk heeft eerst een touw nodig om de emmer te kunnen laten zakken. Haal het touw bij de schildknaap.",en:"The winch first needs a rope before it can lower the bucket. Get the rope from the squire."},depth:8,title:{nl:"Laat de Raaf Zakken",en:"Lower the Raven"},hint:{nl:"Tik op ⟳ Laten zakken precies als de emmer in het midden hangt — alles kleurt dan GROEN. Rood = wachten! Hoe dieper, hoe wilder het slingeren.",en:"Press ⟳ Lower exactly when the bucket hangs in the middle — everything turns GREEN. Red = wait! The deeper you go, the wilder the swing."},setFlag:"gotNecklace",consume:"rope",give:"necklace",solvedText:{nl:"PLONS — de emmer raakt zachtjes het water! De raaf duikt met zijn snavel tussen de rimpels en grist de glinsterende ketting van de bodem. Je draait de hendel terug omhoog; krakend komt de emmer boven, met de raaf erin, trots, een fijne gouden ketting met blauwe edelsteen in zijn snavel! Hij laat hem in je hand vallen, kraait tevreden en vliegt met een laatste “kraa!” weg over de kasteelmuur. Zo’n sieraad hoort vast bij iemand van het hof... de prinses misschien?",en:"SPLASH — the bucket gently touches the water! The raven dips his beak between the ripples and snatches the glittering necklace from the bottom. You crank the handle back up; creaking, the bucket rises, the raven inside, proud, a fine gold necklace with a blue gem in his beak! He drops it into your hand, caws contentedly and, with a last “caw!”, flies off over the castle wall. A jewel like this surely belongs to someone at court... the princess, perhaps?"},resetText:{nl:"ZOEF! Het touw slipt — de emmer schiet weer omhoog. Tik alleen als alles GROEN kleurt.",en:"WHIZZ! The rope slips — the bucket shoots back up. Only tap when everything turns GREEN."}}},{id:"crow",name:{nl:"De Raaf",en:"The Raven"},rect:{x:258,y:56,w:70,h:64},walkTo:{x:286,y:300},hideFlag:"ravenInBucket",look:e=>e.inventory.includes("trinket")?{nl:"De grote, glanzende raaf op het put-dakje gluurt hongerig naar de bronzen munt in je tas. Geef hem de munt — misschien helpt hij je dan iets uit de diepte op te halen.",en:"The big glossy raven on the well roof eyes the bronze coin in your bag hungrily. Give him the coin — perhaps he’ll help fetch something from the deep."}:{nl:"Een grote, glanzende zwarte raaf zit op het dakje van de put en bekijkt je met glinsterende oogjes. Hij gluurt steeds naar je tas — alsof hij iets glimmends ruikt. Raven zijn dol op glanzende dingen. Had je maar iets blinkends om hem te lokken...",en:"A big, glossy black raven sits on the well roof, eyeing you with glittering eyes. He keeps peeking at your bag — as if he smells something shiny. Ravens love bright things. If only you had something gleaming to tempt him..."},use:{trinket:{consume:"trinket",setFlag:"ravenInBucket",text:{nl:"Je houdt de bronzen munt omhoog. De raaf kan zich niet inhouden — hij grist hem uit je hand, kraait “Kraa!” van plezier en springt met munt en al boven op de put-emmer. Met een vrolijk gekras laat hij zich de donkere schacht in zakken... Nu hoef je de emmer alleen nog op te hijsen. Had je maar een touw!",en:"You hold up the bronze coin. The raven can’t resist — he snatches it from your hand, caws “Caw!” with delight and hops onto the well bucket, coin and all. With a cheerful cackle he lowers himself down the dark shaft... Now you only need to haul the bucket up. If only you had a rope!"}}}},{id:"castledoor",name:{nl:"De Kasteeldeur",en:"The Castle Door"},rect:{x:408,y:40,w:76,h:110},walkTo:{x:436,y:248},look:{nl:"De zware eikenhouten kasteeldeur zit op een fors, eeuwenoud slot. Hierachter, ergens diep in de burcht, wordt Finns vader vastgehouden... maar de deur geeft geen krimp. De sleutel ervan is hier nergens te vinden. Misschien is er een andere weg naar binnen...",en:"The heavy oak castle door is held by a big, ancient lock. Beyond it, somewhere deep in the keep, Finn’s father is held captive... but the door will not budge. Its key is nowhere to be found here. Perhaps there is another way in..."}},{id:"forge",name:{nl:"De Smidse",en:"The Forge"},rect:{x:2,y:118,w:78,h:112},walkTo:{x:76,y:252},look:e=>e.flags.swordForged||e.flags.gotSword?{nl:"De smidse van het kasteel. De oven gloeit warm na — hier smeedde je het zwaard van Sir Aldric weer heel.",en:"The castle smithy. The oven still glows warm — here you forged Sir Aldric’s sword whole again."}:e.flags.ovenStoked?{nl:"De oven loeit wit-heet van de houtskool, met het aambeeld en het ijzer ervoor. Gebruik de hamer (of het gebroken zwaard) op het vuur om het zwaard te smeden.",en:"The oven roars white-hot with charcoal, the anvil and iron before it. Tap the fire with the hammer (or the broken sword) to forge the sword."}:{nl:"Een koude smidse onder een afdakje, met een aambeeld en een dode oven. Gooi er houtskool in om het smidsvuur aan te wakkeren.",en:"A cold smithy under a lean-to, with an anvil and a dead oven. Throw in charcoal to kindle the forge fire."},use:{charcoal:{consume:"charcoal",setFlag:"ovenStoked",burst:{x:40,y:188,col:"255,150,40",n:34,up:26,life:1.4},text:{nl:"Je gooit de houtskool op de sintels en blaast aan. WHOESH! Het smidsvuur laait fel op, wit-heet, en een regen van oranje vonken spat omhoog. Nu kun je het zwaard smeden — gebruik de hamer op het vuur.",en:"You throw the charcoal onto the embers and fan it. WHOOSH! The forge fire flares up fierce and white-hot, and a shower of orange sparks bursts upward. Now you can forge the sword — tap the fire with the hammer."}},hammer:{needItem:"swordBroken",needText:{nl:"Je hebt eerst het gebroken zwaard van Sir Aldric nodig — vraag het de schildknaap bij de smidse.",en:"You first need Sir Aldric’s broken sword — ask the squire by the smithy."},requiresFlag:"ovenStoked",requiresText:{nl:"De oven is nog koud. Gooi er eerst houtskool in om het vuur wit-heet op te laten laaien.",en:"The oven is still cold. First throw in charcoal to make the fire roar white-hot."},consume:["swordBroken","hammer"],give:"sword",setFlag:"gotSword",burst:{x:44,y:184,col:"255,210,120",n:26,up:20,life:1.2},text:{nl:"Je loopt naar het ijzer, legt het gebroken zwaard in het wit-hete vuur en slaat met de smidshamer — KLANG! KLANG! De twee gloeiende stukken smelten weer samen. Met een sissende plons in de waterton koel je het af. Je legt de hamer terug bij de smidse en houdt het prachtige, weer hele zwaard van Sir Aldric in handen — breng het naar de schildknaap.",en:"You step to the iron, lay the broken sword in the white-hot fire and strike with the blacksmith’s hammer — CLANG! CLANG! The two glowing pieces fuse back together. With a hissing plunge into the water trough you quench it. You set the hammer back down at the smithy and hold Sir Aldric’s beautiful, whole sword in your hands — bring it to the squire."}},swordBroken:{needItem:"hammer",needText:{nl:"Je hebt de smidshamer nodig om te smeden. Die zit verborgen in het smidsbeeld in de tuin.",en:"You need the blacksmith’s hammer to forge. It’s hidden in the smith statue in the garden."},requiresFlag:"ovenStoked",requiresText:{nl:"De oven is nog koud. Gooi er eerst houtskool in om het vuur wit-heet op te laten laaien.",en:"The oven is still cold. First throw in charcoal to make the fire roar white-hot."},consume:["swordBroken","hammer"],give:"sword",setFlag:"gotSword",burst:{x:44,y:184,col:"255,210,120",n:26,up:20,life:1.2},text:{nl:"Je legt het gebroken zwaard in het wit-hete vuur en slaat het met de smidshamer — KLANG! KLANG! — weer heel. Met een sissende plons in de waterton koel je het af. Je legt de hamer terug bij de smidse en houdt het prachtige zwaard van Sir Aldric in handen — breng het naar de schildknaap.",en:"You lay the broken sword in the white-hot fire and strike it whole with the hammer — CLANG! CLANG! With a hissing plunge into the water trough you quench it. You set the hammer back down at the smithy and hold Sir Aldric’s beautiful sword in your hands — bring it to the squire."}}}},{id:"nut",name:{nl:"Een Pinda",en:"A Peanut"},rect:{x:96,y:234,w:44,h:40},walkTo:{x:116,y:256},hideFlag:"taken_courtyard_nut",gives:{item:"nut",giveText:{nl:"Bij het aambeeld van de smidse ligt een pinda, half uit de dop. Je raapt hem op — vast lekker voor een vogel.",en:"By the smithy anvil lies a peanut, half out of its shell. You pick it up — surely a treat for a bird."},emptyText:{nl:"De pinda zit al in je tas.",en:"The nut is already in your bag."}}},{id:"mushroom",name:{nl:"Gloeizwammen",en:"Glow-caps"},rect:{x:210,y:204,w:46,h:40},walkTo:{x:232,y:288},hideFlag:"taken_courtyard_mushroom",gives:{item:"mushroom",giveText:{nl:"Tegen de voet van de put groeit een trosje gloeizwammen: paddenstoelen met zacht oplichtende blauw-paarse hoedjes. Je plukt ze voorzichtig. Men zegt dat je van hun rook heel slaperig wordt...",en:"Against the foot of the well grows a little bunch of glow-caps: mushrooms with softly glowing blue-purple tops. You pick them carefully. They say their smoke makes you very sleepy..."},emptyText:{nl:"De gloeizwammen bij de put heb je al geplukt.",en:"You’ve already picked the glow-caps by the well."}}},{id:"toGarden",name:{nl:"De Slottuin",en:"The Castle Garden"},rect:{x:112,y:66,w:96,h:98},walkTo:{x:168,y:250},arrow:{x:158,y:142,dir:"up"},exit:{to:"garden",travelText:{nl:"Je loopt onder de begroeide boog door, de bloeiende slottuin in...",en:"You pass under the ivy-clad arch, into the blooming castle garden..."}}}]},garden:{name:{nl:"De Slottuin",en:"The Castle Garden"},bg:"assets/art/scene-garden.webp",bgVariants:[{img:"assets/art/scene-garden-open.webp",flag:"secretGateOpen"},{img:"assets/art/scene-garden-hammer.webp",flag:"statuePuzzleSolved"}],charFilter:"saturate(1.06) brightness(1.05) sepia(0.06) contrast(1.03)",heroShade:.98,entryText:{nl:"De ommuurde slottuin staat vol rozen en klimop. In het midden staat een bronzen smidsbeeld bij zijn aambeeld; links klatert een leeuwenfontein, rechts staat een bankje onder een rozenboog. En daar — tussen de bloemen — wandelt de prinses.",en:"The walled castle garden is full of roses and ivy. A bronze smith statue stands at its centre; a lion fountain trickles to the left, a bench rests under a rose arbour to the right. And there — among the flowers — walks the princess."},playerStart:{x:284,y:300},spawnFrom:{courtyard:{x:284,y:300}},depth:{far:206,near:316,sFar:.72,sNear:1.05},walkable:[{x:30,y:252,w:508,h:62},{x:18,y:218,w:198,h:40},{x:360,y:218,w:178,h:40}],obstacles:[{x:198,y:168,w:174,h:92},{x:0,y:248,w:150,h:72},{x:418,y:248,w:150,h:72},{x:192,y:236,w:38,h:18},{x:340,y:236,w:38,h:18}],overlays:[{img:"assets/art/keyhole.png",x:126,y:158,base:240,scale:.48,appearFlag:"fountainSolved",hideFlag:"secretGateOpen"}],worldItems:[{item:"charcoal",hotspot:"charcoal",x:370,y:201,scale:.6,glowCol:"255,150,60",embers:.9},{item:"trinket",hotspot:"trinket",x:72,y:182,scale:.74,gem:!0,glintOnly:!0,glintScale:.48,glintWide:1.55,glowCol:"255,210,130"}],npcs:[{id:"princess",sprite:"princess",sway:.02,filter:"brightness(0.78) saturate(0.92)",flip:!0,x:424,y:250,scale:1},{id:"gardenParrot",sprite:"parrot",x:508,y:204,scale:.42,flip:!0,peck:!0,peckAmt:.35,filter:"brightness(0.95) saturate(0.95)"}],fx:{fountain:{jets:[{sx:65,sy:155},{sx:67,sy:156}],len:25,wx:66,wy:182},emberGlow:{x:370,y:202,r:14,doneFlag:"taken_garden_charcoal"}},hotspots:[{id:"princess",name:{nl:"De Prinses",en:"The Princess"},face:"assets/art/face-princess.png",rect:{x:400,y:170,w:60,h:90},walkTo:{x:398,y:296},choice:{prompt:{nl:"De prinses kijkt je met een glimlach aan. “Waarover wil je praten, Finn?”",en:"The princess looks at you with a smile. “What shall we talk about, Finn?”"},options:[{label:{nl:"Wie ben je?",en:"Who are you?"},text:{nl:"“Ik ben de kleindochter van Sir Aldric, de Leeuw van Eldoria. Sinds grootvader viel hangt er een stilte over het kasteel — en mijn vader, de koning, ontvangt niemand meer.”",en:"“I am the granddaughter of Sir Aldric, the Lion of Eldoria. Since grandfather fell a hush has lain over the castle — and my father the king sees no one anymore.”"}},{label:{nl:"Gaat het wel met je?",en:"Are you alright?"},text:{nl:"Haar glimlach verflauwt. “Eerlijk gezegd... niet helemaal. Ik ben iets dierbaars kwijt — de gouden ketting van mijn moeder. Hij gleed van mijn hals, diep de oude put op de binnenplaats in. Ik zou er álles voor geven om hem terug te zien.”",en:"Her smile fades. “Honestly... not quite. I’ve lost something dear — my mother’s gold necklace. It slipped from my neck, deep down the old well in the courtyard. I’d give anything to see it again.”"}},{label:{nl:"Mijn vader",en:"My father"},text:e=>e.flags.fountainSolved?{nl:"Je vertelt zacht over je gevangen vader. Ze knijpt in je hand. “Het verborgen slot naast de leeuwenfontein is nu onthuld — de sleutel die ik je gaf past erop. Ga erdoorheen, Finn, en wees voorzichtig.”",en:"You speak softly of your captive father. She squeezes your hand. “The hidden lock beside the lion fountain is revealed now — the key I gave you fits it. Go through it, Finn, and be careful.”"}:e.flags.gaveNecklace?{nl:"Je vertelt zacht over je gevangen vader. Ze knijpt in je hand. “Ik gaf je de sleutel — los nu de schuifpuzzel bij de leeuwenfontein op. Dan verschijnt het verborgen slot in de muur. Wees voorzichtig, Finn.”",en:"You speak softly of your captive father. She squeezes your hand. “I gave you the key — now solve the sliding puzzle at the lion fountain. The hidden lock will appear in the wall. Be careful, Finn.”"}:{nl:"Je vertelt zacht dat je vader ergens diep in het kasteel gevangen wordt gehouden. Ze knijpt even in je hand en aarzelt. “Wees voorzichtig, Finn. Er ís misschien een verborgen weg naar binnen... maar zo’n geheim kan ik alleen toevertrouwen aan iemand die ik écht ken.” Ze kijkt je peinzend aan.",en:"You tell her softly that your father is held captive deep in the castle. She squeezes your hand and hesitates. “Be careful, Finn. There may be a hidden way in... but such a secret I can only entrust to someone I truly know.” She gives you a thoughtful look."}},{label:{nl:"Tot ziens",en:"Goodbye"},text:{nl:"“Blijf niet te lang weg, Finn,” zegt ze zacht, en ze glimlacht.",en:"“Don’t stay away too long, Finn,” she says softly, and smiles."}}]},look:e=>e.flags.gaveNecklace?e.flags.fountainSolved?{nl:"De prinses straalt met de ketting van haar moeder om haar hals. “Het verborgen slot naast de leeuwenfontein is onthuld, Finn — jouw sleutel past erop. Wees voorzichtig daarachter, en kom alsjeblieft weer terug.”",en:"The princess beams, her mother’s necklace around her neck. “The hidden lock beside the lion fountain is revealed now, Finn — your key fits it. Be careful beyond it, and please come back to me.”"}:{nl:"De prinses draagt de ketting van haar moeder weer en straalt. “Dankzij jou, Finn. Los de schuifpuzzel bij de leeuwenfontein op, dan verschijnt het verborgen slot in de muur — daar past de sleutel die ik je gaf. En kom alsjeblieft weer terug.”",en:"The princess wears her mother’s necklace again and beams. “Thanks to you, Finn. Solve the sliding puzzle at the lion fountain and the hidden lock will appear in the wall — the key I gave you fits it. And please, come back to me.”"}:e.flags.metPrincess?{nl:"De prinses zucht. “Die ketting was alles wat ik nog van mijn moeder had — hij viel diep in de oude put op de binnenplaats. Kon iemand hem er maar uithalen...”",en:"The princess sighs. “That necklace was all I had left of my mother — it fell deep down the old well in the courtyard. If only someone could fish it out...”"}:{nl:"Tussen de rozen wandelt de prinses op wie Finn al sinds zijn jeugd stiekem verliefd is. Zijn hart bonkt. Ze kijkt op, een beetje droevig: “Een nieuw gezicht in mijn tuin... vergeef me dat ik geen vrolijk gezelschap ben — ik ben de ketting van mijn moeder verloren, gevallen in de oude put.”",en:"Among the roses walks the princess Finn has secretly loved since childhood. His heart pounds. She looks up, a little sad: “A new face in my garden... forgive me for being poor company — I’ve lost my mother’s necklace, dropped down the old well.”"},use:{necklace:{consume:"necklace",give:"key",setFlag:"gaveNecklace",text:{nl:"Je houdt de prinses de gouden ketting voor. “Mijn moeders ketting — je hebt hem gevonden!” Met tranen in haar ogen doet ze hem om en drukt je een oude sleutel in de hand. “Die past op het verborgen slot naast de leeuwenfontein: de geheime poort. Bijna niemand weet ervan.” Dan kijkt ze ernstig. “Pas op, Finn. Die gang komt uit in de oude bibliotheek, en daar woont een boze tovenaar. Hij wil de macht over heel Eldoria grijpen. Laat je niet betrappen. Wees dapper.”",en:"You hold out the gold necklace to the princess. “My mother’s necklace — you found it!” Tears in her eyes, she fastens it on and presses an old key into your hand. “It fits the hidden lock beside the lion fountain: the secret gate. Almost no one knows of it.” Then she looks serious. “Be careful, Finn. That passage leads to the old library, where an evil wizard lives. He wants to seize power over all of Eldoria. Don’t let him catch you. Be brave.”"}},sword:{keep:!0,setFlag:"showedSword",text:{nl:"Je toont de prinses het opnieuw gesmede zwaard. “Het zwaard van mijn grootvader — weer heel!” fluistert ze, en haar ogen glanzen. “Met jou als ridder zou Eldoria niets te vrezen hebben, Finn.” Je staat te blozen en weet even niets te zeggen.",en:"You show the princess the reforged sword. “My grandfather’s blade — whole again!” she whispers, her eyes shining. “With you as its knight, Eldoria would have nothing to fear, Finn.” You blush and, for a moment, find nothing to say."}}},setFlag:"metPrincess"},{id:"fountain",name:{nl:"De Leeuwenkop",en:"The Lion’s Head"},rect:{x:26,y:102,w:66,h:64},walkTo:{x:96,y:244},hideFlag:"secretGateOpen",look:e=>e.flags.fountainSolved?{nl:"De leeuwenkop spuwt nog water — en in de muur rechts van de fontein is nu een ijzeren sleutelgat verschenen. Het wacht op de juiste sleutel.",en:"The lion’s head still spouts water — and in the wall to the right of the fountain an iron keyhole has appeared. It waits for the right key."}:{nl:"Een stenen leeuwenkop spuwt water in een schelpvormig bekken. Op de bodem ligt, vertroebeld door het water, een stenen wapen-mozaïek dat in losse stukken is geschoven. Schuif de stukken weer op hun plaats om te zien wat het in beweging zet.",en:"A stone lion spouts water into a shell-shaped basin. On the floor, blurred by the water, lies a stone crest-mosaic shuffled into loose pieces. Slide them back into place to see what it sets in motion."},slidePuzzle:{size:3,img:"assets/art/puzzle-fountain.webp",title:{nl:"Het Wapen in de Fontein",en:"The Crest in the Fountain"},setFlag:"fountainSolved",burst:{x:60,y:150},solvedText:{nl:"Het mozaïek klikt compleet op zijn plaats — het wapen van Sir Aldric, de Leeuw van Eldoria. In de muur rechts van de fontein schuift met een steenachtig gerommel een paneel opzij, en daar verschijnt een ijzeren sleutelgat, diep in de steen verzonken. Waar zou de sleutel ervan op liggen?",en:"The mosaic clicks complete — the arms of Sir Aldric, the Lion of Eldoria. In the wall to the right of the fountain a panel grinds aside, revealing an iron keyhole set deep into the stone. Where might its key be?"}},use:{key:{requiresFlag:"fountainSolved",requiresText:{nl:"Er is hier nog geen slot te zien. Los eerst de schuifpuzzel in de fontein op.",en:"There’s no lock to be seen here yet. Solve the fountain’s sliding puzzle first."},puzzleFallback:!0,keep:!1,consume:"key",setFlag:"secretGateOpen",text:{nl:"Je steekt de oude sleutel in het slot in de muur en draait. Met een diepe, knarsende dreun schuift een hele muurpartij opzij — de geheime poort gaat open! Een koele, donkere gang gaapt erachter, diep het kasteel in.",en:"You slide the old key into the lock in the wall and turn. With a deep, grinding boom a whole section of wall slides aside — the secret gate opens! A cool, dark passage gapes beyond, deep into the castle."}}}},{id:"wallLock",name:{nl:"Het Sleutelgat",en:"The Keyhole"},rect:{x:108,y:144,w:46,h:48},walkTo:{x:132,y:244},appearFlag:"fountainSolved",hideFlag:"secretGateOpen",look:{nl:"Een ijzeren sleutelgat, diep in de muur verzonken. Het wacht op de juiste sleutel.",en:"An iron keyhole set deep into the wall. It waits for the right key."},use:{key:{keep:!1,consume:"key",setFlag:"secretGateOpen",text:{nl:"Je steekt de oude sleutel in het slot in de muur en draait. Met een diepe, knarsende dreun schuift een hele muurpartij opzij — de geheime poort gaat open! Een koele, donkere gang gaapt erachter, diep het kasteel in.",en:"You slide the old key into the lock in the wall and turn. With a deep, grinding boom a whole section of wall slides aside — the secret gate opens! A cool, dark passage gapes beyond, deep into the castle."}}}},{id:"secretGate",name:{nl:"De Geheime Poort",en:"The Secret Gate"},rect:{x:104,y:116,w:62,h:106},walkTo:{x:132,y:244},appearFlag:"secretGateOpen",arrow:{x:134,y:162,dir:"up"},exit:{to:"library",travelText:{nl:"Je stapt door de open geheime poort naast de leeuwenfontein. Een koele, donkere gang loopt diep het kasteel in en komt uit in een stille, stoffige bibliotheek vol oude boeken...",en:"You step through the open secret gate beside the lion fountain. A cool, dark passage runs deep into the castle and opens into a quiet, dusty library full of ancient books..."}}},{id:"gstatue",name:{nl:"Het Beeld van de Smid",en:"The Statue of the Smith"},rect:{x:232,y:90,w:96,h:150},walkTo:{x:286,y:296},look:e=>e.flags.statuePuzzleSolved?{nl:"Het vakje onder in de sokkel staat open en leeg — de zware smidshamer zit nu in je tas. Tijd om het zwaard te smeden bij de smidse.",en:"The niche in the base of the plinth stands open and empty — the heavy blacksmith’s hammer is in your bag now. Time to forge the sword at the smithy."}:e.flags.gotSmithPhrase?{nl:"Het bronzen beeld van de smid bij zijn aambeeld. In de sokkel zijn woorden gebeiteld — tik de geheime woorden van de smid aan in de juiste volgorde.",en:"The bronze statue of the smith at his anvil. Words are carved into the plinth — tap the smith’s secret words in the right order."}:{nl:"Een bronzen beeld van een smid bij zijn aambeeld. In de sokkel zijn allerlei woorden gebeiteld. Je moet de juiste geheime woorden aantikken — maar welke, en in welke volgorde? Wie zou dat weten?",en:"A bronze statue of a smith at his anvil. All sorts of words are carved into the plinth. You must tap the right secret words — but which ones, and in what order? Who might know?"},symbolPuzzle:{img:"assets/art/puzzle-words.webp",title:{nl:"De Geheime Woorden van de Smid",en:"The Smith’s Secret Words"},hint:{nl:"Tik de geheime spreuk van de smid woord voor woord aan, in de juiste volgorde. De woorden zijn Engels en veel ervan zijn afleiders. Weet je de spreuk niet? Vraag het de papagaai in de tuin.",en:"Tap the smith’s secret saying word by word, in the right order. Many words are decoys. Don’t know the saying? Ask the parrot in the garden."},zones:[{key:"rust",left:1,top:3,width:23,height:22},{key:"fire",left:26,top:3,width:23,height:22},{key:"gold",left:51,top:3,width:23,height:22},{key:"true",left:76,top:3,width:23,height:22},{key:"steel",left:1,top:28,width:23,height:22},{key:"water",left:26,top:28,width:23,height:22},{key:"forges",left:51,top:28,width:23,height:22},{key:"moon",left:76,top:28,width:23,height:22},{key:"ice",left:1,top:53,width:23,height:22},{key:"king",left:26,top:53,width:23,height:22},{key:"only",left:51,top:53,width:23,height:22},{key:"stone",left:76,top:53,width:23,height:22},{key:"wood",left:1,top:78,width:23,height:22},{key:"silver",left:26,top:78,width:23,height:22},{key:"smoke",left:51,top:78,width:23,height:22},{key:"glass",left:76,top:78,width:23,height:22}],symbols:[{key:"only",label:{nl:"Only",en:"Only"}},{key:"fire",label:{nl:"Fire",en:"Fire"}},{key:"forges",label:{nl:"Forges",en:"Forges"}},{key:"true",label:{nl:"True",en:"True"}},{key:"steel",label:{nl:"Steel",en:"Steel"}}],sequence:["only","fire","forges","true","steel"],setFlag:"statuePuzzleSolved",give:"hammer",solvedText:{nl:"De woorden lichten één voor één op — ONLY... FIRE... FORGES... TRUE... STEEL! (Alleen vuur smeedt echt staal.) Met een steenachtig gerommel schuift een vakje in de sokkel open. Daarin ligt een zware smidshamer! Je neemt hem mee. Hiermee kun je bij de smidse het zwaard van Sir Aldric weer smeden.",en:"The words light up one by one — ONLY... FIRE... FORGES... TRUE... STEEL! With a stony rumble a niche slides open in the plinth. Inside lies a heavy blacksmith’s hammer! You take it. With this you can forge Sir Aldric’s sword again at the smithy."},resetText:{nl:"De woorden doven. Verkeerde volgorde — begin opnieuw. (Vraag de papagaai naar de spreuk.)",en:"The words go dark. Wrong order — start over. (Ask the parrot for the saying.)"},doneText:{nl:"Het vakje is open en leeg; de hamer zit in je tas.",en:"The niche is open and empty; the hammer is in your bag."}}},{id:"parrot",name:{nl:"De Papagaai",en:"The Parrot"},face:"assets/art/face-parrot.png",rect:{x:482,y:172,w:66,h:66},walkTo:{x:486,y:244},choice:{prompt:{nl:"De papagaai legt zijn kopje scheef. “Krrak! Wil je iets weten?”",en:"The parrot tilts his head. “Squawk! Want to know something?”"},options:[{label:{nl:"Wie ben jij?",en:"Who are you?"},text:{nl:"“Krrak! Ik ben de oudste papagaai van Eldoria. Ik zit hier al langer dan de koning regeert — en ik vergeet níets!”",en:"“Squawk! I’m the oldest parrot in Eldoria. I’ve perched here longer than the king has reigned — and I forget nothing!”"}},{label:{nl:"Heb je nieuws voor me?",en:"Any news for me?"},setFlag:"parrotToldEntrance",text:{nl:"“Krrak! Nieuws? Hihí... Ik klap uit de school: náást de leeuwenfontein in de tuin zit een geheime ingang in de muur, diep het kasteel in! Niemand weet ervan — behalve ik. Maar er zit vast een goed slot op, krrak.”",en:"“Squawk! News? Hehe... Let me spill a secret: beside the lion fountain in the garden there’s a hidden entrance in the wall, deep into the castle! No one knows of it — except me. But it surely has a good lock on it, squawk.”"}},{label:{nl:"Het geheim van de smid?",en:"The smith’s secret?"},text:e=>e.flags.gotSmithPhrase?{nl:"“Krrak! De spreuk van de smid: ONLY... FIRE... FORGES... TRUE... STEEL! In díe volgorde!” (Engels voor: alleen vuur smeedt echt staal.)",en:"“Squawk! The smith’s saying: ONLY... FIRE... FORGES... TRUE... STEEL! In that order!”"}:{nl:"“Krrak! Een hongerige vogel praat niet. Geef me een pinda — er ligt er een bij het aambeeld op het plein — en ik fluister de geheime spreuk van de smid.”",en:"“Squawk! A hungry bird won’t talk. Give me a peanut — there’s one by the anvil in the courtyard — and I’ll whisper the smith’s secret saying.”"}},{label:{nl:"Dag papagaai",en:"Bye, parrot"},text:{nl:"“Krrak! Tot kijk!” Hij schudt vrolijk zijn veren.",en:"“Squawk! See you!” He ruffles his feathers happily."}}]},look:{nl:"Een kleurrijke groene papagaai zit op het bankje en bekijkt je nieuwsgierig met scheef kopje. Hij lijkt graag te kletsen.",en:"A colourful green parrot perches on the bench, eyeing you with a curious tilt of the head. He seems to love a chat."},use:{nut:{consume:"nut",setFlag:"gotSmithPhrase",text:{nl:"Je geeft de papagaai de pinda. Hij kraakt de schil behendig open, smult van de pinda, en kwettert dan de geheime spreuk van de smid: “Krrak! ONLY... FIRE... FORGES... TRUE... STEEL! In díe volgorde!” Dat is Engels en betekent: “alleen vuur smeedt echt staal”. Tik de vijf woorden in díe volgorde aan bij het smidsbeeld. (Tik op de papagaai om de spreuk nog eens te horen.)",en:"You give the parrot the peanut. He cracks the shell open deftly, gobbles up the nut, and then chatters the smith’s secret saying: “Squawk! ONLY... FIRE... FORGES... TRUE... STEEL! In that order!” You commit the five words to memory — tap them in that order at the smith statue. (Tap the parrot to hear the saying again.)"}}}},{id:"charcoal",name:{nl:"De Rechter Vuurkorf",en:"The Right Fire Basket"},rect:{x:346,y:182,w:46,h:40},walkTo:{x:368,y:268},hideFlag:"taken_garden_charcoal",gives:{item:"charcoal",giveText:{nl:"In de ijzeren vuurkorf rechts van het smidsbeeld ligt een hoopje houtskool, de sintels gloeien nog zachtjes na. Je schept een flinke handvol in je tas — precies wat een smidsvuur nodig heeft.",en:"In the iron fire basket right of the smith statue lies a heap of charcoal, its embers still faintly aglow. You scoop a good handful into your bag — just what a forge fire needs."},emptyText:{nl:"De vuurkorf is leeg geschept; de houtskool zit al in je tas.",en:"You already scooped the basket empty; the charcoal is in your bag."}}},{id:"brazierL",name:{nl:"De Linker Vuurkorf",en:"The Left Fire Basket"},rect:{x:202,y:210,w:28,h:42},walkTo:{x:210,y:270},look:{nl:"Een ijzeren vuurkorf op drie poten, links van het smidsbeeld. Deze is helemaal leeg — kaal, koud ijzer, geen kooltje te bekennen.",en:"An iron fire basket on three legs, left of the smith statue. This one is completely empty — bare, cold iron, not a coal in sight."}},{id:"trinket",name:{nl:"Iets glimmends in de fontein",en:"Something shiny in the fountain"},rect:{x:50,y:180,w:44,h:28},walkTo:{x:96,y:244},hideFlag:"taken_garden_trinket",gives:{item:"trinket",giveText:{nl:"Op de bodem van het schelpbekken ligt iets te glinsteren onder het kabbelende water — een glanzende bronzen munt! Je vist hem eruit. Zoiets glimmends... daar is een raaf vast dol op.",en:"On the floor of the shell basin something glints beneath the rippling water — a gleaming bronze coin! You fish it out. Something this shiny... a raven would surely love it."},emptyText:{nl:"De bronzen munt zit al in je tas.",en:"The bronze coin is already in your bag."}}},{id:"bench",name:{nl:"Het Bankje",en:"The Bench"},rect:{x:470,y:148,w:92,h:82},walkTo:{x:486,y:244},look:{nl:"Een verweerd houten bankje onder een boog van klimrozen. Een fijne plek om samen te zitten... als je dapper genoeg bent om het te vragen.",en:"A weathered wooden bench under an arch of climbing roses. A fine place to sit together... if you’re brave enough to ask."}},{id:"toCourtyard",name:{nl:"Terug naar de Binnenplaats",en:"Back to the Courtyard"},rect:{x:148,y:260,w:150,h:56},walkTo:{x:200,y:306},arrow:{x:200,y:282,dir:"down"},exit:{to:"courtyard",travelText:{nl:"Je loopt de tuin weer uit, terug naar de binnenplaats.",en:"You leave the garden, back to the courtyard."}}}]},library:{name:{nl:"De Kasteelbibliotheek",en:"The Castle Library"},bg:"assets/art/scene-library.webp",bgVariants:[{img:"assets/art/scene-library-night-dooropen.webp",flags:["altarSolved","eclipseActive"]},{img:"assets/art/scene-library-night-doorclosed.webp",flag:"eclipseActive"},{img:"assets/art/scene-library-open.webp",flag:"libRelit"},{img:"assets/art/scene-library-nacht-deur.webp",flag:"altarSolved"}],charFilter:"saturate(1.02) brightness(0.88) sepia(0.14) contrast(1.04)",heroShade:.66,entryText:{nl:"De geheime gang komt uit in een stille kasteelbibliotheek. Hoge boekenkasten reiken tot het plafond, bij het grote raam staat een koperen telescoop, en midden in de zaal gloeit een boek op een sierlijke lessenaar. Een oude tovenaar tuurt erin, en op de vensterbank zit... de raaf!",en:"The secret passage opens into a quiet castle library. Tall bookcases rise to the ceiling, a brass telescope stands by the great window, and in the middle of the hall a book glows on an ornate lectern. An old wizard peers into it, and on the windowsill sits... the raven!"},playerStart:{x:300,y:298},spawnFrom:{garden:{x:300,y:298}},depth:{far:210,near:320,sFar:.96,sNear:1.46},walkable:[{x:64,y:250,w:440,h:58},{x:150,y:224,w:280,h:30}],obstacles:[{x:308,y:206,w:48,h:50},{x:416,y:244,w:118,h:60},{x:160,y:238,w:56,h:34}],overlays:[],fx:{bookSparkle:{x:278,y:150,r:24,doneFlag:"altarSolved"},mageGlow:{x:153,y:138,r:10,a:.42,sparkle:!0,hideFlag:"wizardTripping"},candleBowl:{x:94,y:262,w:46,h:66,img:"assets/art/altar-censer.webp",smokeFlag:"wizardTripping"}},npcs:[{id:"librarian",sprite:"librarian",blinkSprite:"librarian-sleep",idleBreathe:!0,x:192,y:256,scale:.85,aweSwayMul:3.2,flip:!1,filter:"brightness(0.84) saturate(1.14)",aweSprite:"librarian-sleep",aweFlag:"wizardTripping",tripFx:!0},{id:"libRaven",sprite:"ravenPerch",x:366,y:155,scale:1.02,flip:!1,peck:!0,peckAmt:.3}],worldItems:[],hotspots:[{id:"toGardenLib",name:{nl:"Terug naar de Tuin",en:"Back to the Garden"},rect:{x:6,y:250,w:92,h:62},walkTo:{x:70,y:300},arrow:{x:80,y:268,dir:"down"},exit:{to:"garden",travelText:{nl:"Je sluipt de gang weer door, terug naar de slottuin.",en:"You slip back through the passage, into the castle garden."}}},{id:"toDungeon",name:{nl:"De Geheime Deur",en:"The Secret Door"},rect:{x:82,y:104,w:84,h:118},walkTo:{x:150,y:254},arrow:{x:122,y:150,dir:"up"},requiresFlag:"altarSolved",exit:{to:"dungeon",travelText:{nl:"Je glipt door de geheime deur achter de boekenkast. Een smalle, klamme wenteltrap voert je diep onder het kasteel, tot je uitkomt in een donkere kerker...",en:"You slip through the secret door behind the bookcase. A narrow, clammy spiral stair takes you deep beneath the castle, until you emerge in a dark dungeon..."}}},{id:"libRaven",name:{nl:"De Raaf",en:"The Raven"},rect:{x:338,y:118,w:42,h:58},walkTo:{x:344,y:252},look:e=>e.flags.altarSolved?{nl:"“Krra! De geheime deur staat open — de trap af, de kerker in! En onthoud: wat een wachter niet zíet, kan hij niet tegenhouden...”",en:"“Caw! The secret door stands open — down the stairs, into the dungeon! And remember: what a guard cannot SEE, he cannot stop...”"}:e.flags.sawSigns?{nl:"“Krra! De onzichtbaarheidsspreuk is van jou! Nu de geheime deur: kijk door de TELESCOOP nu de sterren schijnen — in het hart van de hemelschijf staan drie tekens onder elkaar. Draai de schijven van het Deurzegel tot ze alle drie bovenaan staan — en trek aan de hendel!”",en:"“Caw! The invisibility spell is yours! Now the secret door: look through the TELESCOPE while the stars shine — in the heart of the sky-wheel three signs sit one above the other. Turn the Door Seal discs until all three sit at the top — and pull the lever!”"}:e.flags.eclipseActive?{nl:"“Krra! De zon is gedoofd — het boek is nu te LÉZEN! Tik het aan: daarin wacht de spreuk van de onzichtbaarheid.”",en:"“Caw! The sun is dark — the book can be READ now! Tap it: the spell of invisibility waits inside.”"}:e.flags.gotEclipseSpell?{nl:"“Krra! Je hebt de spreuk! Tik hem aan in je tas en spreek hem uit — dan dooft de zon en kun je het gloeiende boek eindelijk lezen.”",en:"“Caw! You have the spell! Tap it in your bag and speak it — the sun will darken and you can finally read the glowing book.”"}:e.flags.wizardTripping?{nl:"“Krra! Moet je hem zien knikkebollen... Snél — kijk naar het ZONNESTELSEL op de sokkel rechts! Draai de hemelschijf tot zon, maan en ster op één lijn staan — dáár zit de zonsverduistering-spreuk in.”",en:"“Caw! Look at him snooze... Quick — look at the SOLAR SYSTEM on the pedestal to the right! Turn the celestial disc until sun, moon and star line up — that is where the eclipse spell hides.”"}:{nl:"De raaf zit parmantig op de vensterbank. “Krra! Die oude tovenaar wijkt geen duimbreed van zijn instrumenten... Maar ik weet hoe je hem in slaap krijgt: gloeizwammen! Die groeien bij de oude put op de binnenplaats. Leg ze in de schaal met kaarsen náást hem — van de rook wordt hij doodmoe!”",en:"The raven perches proudly on the windowsill. “Caw! That old wizard will not budge an inch from his instruments... But I know how to send him to sleep: glow-caps! They grow by the old well in the courtyard. Lay them in the bowl of candles beside him — the smoke will make him terribly sleepy!”"}},{id:"shelves",name:{nl:"De Boekenkasten",en:"The Bookcases"},rect:{x:446,y:36,w:84,h:118},walkTo:{x:404,y:282},look:{nl:"Rijen op rijen eeuwenoude boeken: kronieken van Eldoria, sterrenkaarten, verboden spreukenboeken. Maar één boek, op de lessenaar, gloeit zachtjes — dáár moet je zijn.",en:"Rows upon rows of ancient tomes: chronicles of Eldoria, star charts, forbidden spellbooks. But one book, on the lectern, glows softly — that is the one you want."}},{id:"candleBowl",name:{nl:"Het Kaarsen-Altaar",en:"The Candle Altar"},rect:{x:86,y:196,w:52,h:66},walkTo:{x:150,y:262},look:e=>e.flags.wizardTripping?{nl:"Op het altaar smeulen de gloeizwammen tussen de kaarsen; een zachte, slaperige rook kringelt omhoog. De tovenaar staat ernaast te knikkebollen en te gapen.",en:"On the altar the glow-caps smoulder among the candles; soft, sleepy smoke curls up. The wizard stands beside it, nodding off and yawning."}:{nl:"Op een klein stenen altaar rust een bronzen schaal, omringd door drie flakkerende kaarsen. In de schaal smeulen wat gedroogde kruiden en een ijle rooksliert kringelt op. Wat je hierin legt, gaat zachtjes smeulen... misschien iets waar je slaperig van wordt?",en:"On a small stone altar rests a bronze bowl, ringed by three flickering candles. Some dried herbs smoulder in it and a thin wisp of smoke curls up. Whatever you lay in here will gently smoulder... perhaps something that makes you sleepy?"},use:{mushroom:{consume:"mushroom",setFlag:"wizardTripping",text:{nl:"Je legt de gloeizwammen voorzichtig in de bronzen schaal. De kaarsvlammen likken eraan en een zachte, zoetige rook kringelt omhoog, recht onder de neus van de tovenaar. Hij gaapt... en gaapt nog eens. “Ooooh... wat ben ik ineens moe... nog vijf minuutjes...” mompelt hij, en hij dommelt staand in. Het gloeiende boek is nu onbewaakt!",en:"You gently lay the glow-caps in the bronze bowl. The candle flames lick at them and soft, sweet smoke curls up, right under the wizard’s nose. He yawns... and yawns again. “Ooooh... I’m suddenly so sleepy... five more minutes...” he mumbles, and dozes off standing up. The glowing book is unguarded now!"}}}},{id:"librarian",name:{nl:"De Tovenaar",en:"The Wizard"},face:"assets/art/face-librarian.png",rect:{x:174,y:140,w:54,h:122},walkTo:{x:244,y:268},look:e=>e.flags.wizardTripping?{nl:"De oude tovenaar staat te knikkebollen en wiebelt slaperig heen en weer. “Zzz... wat een mooie sterretjes... zzz...” mompelt hij met zijn ogen dicht. Het gloeiende boek ziet hij allang niet meer.",en:"The old wizard is nodding off, swaying sleepily from side to side. “Zzz... such pretty little stars... zzz...” he mumbles, eyes closed. He has long forgotten the glowing book."}:{nl:"De boze tovenaar kijkt op van het gloeiende boek en schatert het uit: “Hahá! Een JOCHIE? Kom jíj mij bestelen, ukkie? Ik grijp binnenkort de macht over heel Eldoria — en jij denkt dat je mijn sterrenspreuken kunt aanraken? Wegwezen, kleine nieuwsgierneus!” Hij lacht kakelend en buigt zich weer over het boek. Maar stiekem gaapt hij — die tovenaar kan wel een dutje gebruiken. (De raaf op de vensterbank grinnikt: “Krra... gloeizwammen, in de schaal met kaarsen!”)",en:"The evil wizard looks up from the glowing book and bursts out laughing: “Haha! A BOY? You, rob ME, little one? Soon I shall seize power over all Eldoria — and you think you can touch my star spells? Off you go, little busybody!” He cackles and bends back over the book. But he sneaks a yawn — this wizard could use a nap. (The raven on the sill snickers: “Caw... glow-caps, in the bowl of candles!”)"},use:{mushroom:{needText:{nl:"“Afblijven, jochie!” De tovenaar slaat je hand weg — zomaar iets aanpakken doet hij niet. Maar kijk, naast hem staat een schaal met kaarsen... leg de gloeizwammen dáárin, dan doet de rook het werk.",en:"“Hands off, boy!” The wizard swats your hand away — he won’t take anything from you. But look, beside him stands a bowl of candles... place the glow-caps in THERE, and the smoke will do the work."}}}},{id:"spelltome",name:{nl:"Het Gloeiende Boek",en:"The Glowing Book"},rect:{x:228,y:122,w:92,h:94},walkTo:{x:300,y:256},look:e=>e.flags.altarSolved?{nl:"Het grote boek rust. De onzichtbaarheidsspreuk staat veilig in jouw toverboek en de geheime deur staat open.",en:"The great book rests. The invisibility spell sits safely in your spellbook and the secret door stands open."}:e.flags.sawSigns?{nl:"De onzichtbaarheidsspreuk staat in je toverboek. De laatste bladzijde wijst naar de telescoop: tijdens de zonsverduistering toont het hart van de hemelschijf drie tekens onder elkaar (Ψ, ♃, ♄). Zet ze in die volgorde bovenaan op het Deurzegel — buitenste, middelste, binnenste schijf — en trek aan de hendel!",en:"The invisibility spell is in your spellbook. The last page points to the telescope: during the eclipse, the heart of the sky-wheel shows three signs one above the other (Ψ, ♃, ♄). Set them in that order at the top of the Door Seal — outer, middle, inner disc — and pull the lever!"}:e.flags.gotEclipseSpell&&e.flags.eclipseActive?{nl:"Nu de zon verduisterd is, gloeien de toverletters helder op — het boek is te LEZEN! Tik het aan en ontvang wat erin geschreven staat.",en:"Now that the sun is darkened, the magic letters glow bright — the book can be READ! Tap it and receive what is written inside."}:e.flags.gotEclipseSpell?{nl:"Bij daglicht toont het grote boek alleen vage krabbels — alleen bij het licht van een zonsverduistering zijn de toverletters te lezen... Spreek de spreuk uit bij het raam en lees dán het boek.",en:"In daylight the great book shows only faint scribbles — only by the light of a solar eclipse can the magic letters be read... Cast the spell at the window, then read the book."}:e.flags.wizardTripping?{nl:"Het boek gloeit zacht, maar de bladzijden tonen enkel vreemde krabbels. In de kantlijn staat een kleine tekening: het ZONNESTELSEL op de sokkel, met draaiende ringen eromheen... Bekijk dat zonnestelsel eens!",en:"The book glows softly, but its pages show only strange scribbles. In the margin sits a small drawing: the SOLAR SYSTEM on the pedestal, with turning rings around it... Take a look at that solar system!"}:{nl:"Een groot boek op de lessenaar gloeit zacht. De tovenaar houdt het scherp in de gaten — je durft het niet aan te raken.",en:"A great book on the lectern glows softly. The wizard watches it sharply — you dare not touch it."},signsBook:{requiresFlag:"wizardTripping",blockedText:{nl:"“Niemand raakt de sterrenspreuken aan!” snauwt de tovenaar. Zolang hij erbij is, kom je niet bij het boek. (De raaf fluistert: “Krra... gloeizwammen, in de schaal met kaarsen!”)",en:"“No one touches the star spells!” snaps the wizard. While he is watching you cannot reach the book. (The raven whispers: “Caw... glow-caps, in the bowl of candles!”)"},eclipseFlag:"eclipseActive",dayText:e=>e.flags.gotEclipseSpell?{nl:"De bladzijde toont twee tekeningen van een verdwijnende mantel — maar de toverwoorden zelf blijven onzichtbaar. Alleen bij het licht van een ZONSVERDUISTERING gloeien ze op... Spreek de zonsverduistering-spreuk uit bij het raam en lees dán het boek.",en:"The page shows two drawings of a vanishing cloak — but the spell words themselves stay hidden. Only by the light of a SOLAR ECLIPSE do they glow into view... Cast the eclipse spell at the window, then read the book."}:{nl:"De bladzijde toont twee tekeningen van een verdwijnende mantel — maar de toverwoorden zelf blijven onzichtbaar. Ze gloeien alleen op bij het licht van een ZONSVERDUISTERING. Om de zon te verduisteren heb je een spreuk nodig — bekijk het koperen ZONNESTELSEL op de sokkel.",en:"The page shows two drawings of a vanishing cloak — but the spell words themselves stay hidden. They only glow by the light of a SOLAR ECLIPSE. To darken the sun you need a spell — examine the brass SOLAR SYSTEM on the pedestal."},setFlag:["sawSigns","gotInvisSpell"],give:"invisspell",firstText:{nl:"Bij het spookachtige eclipslicht worden de krabbels leesbaar: “Velum Invisibilis”! Een zilveren bladzijde schrijft zich over in jouw toverboek — de SPREUK VAN ONZICHTBAARHEID is van jou! (En op de laatste bladzijde: een tekening van de telescoop en een hemelschijf vol sterrenbeelden — “als de sterren overdag schijnen, toont het hart van de hemel de volgorde”...)",en:"In the ghostly eclipse light the scribbles become readable: “Velum Invisibilis”! A silver page writes itself into your spellbook — the SPELL OF INVISIBILITY is yours! (And on the last page: a drawing of the telescope and a sky-wheel full of constellations — “when the stars shine by day, the heart of the sky reveals the order”...)"},dayZoomImg:"assets/art/book-spell.webp",zoomImg:"assets/art/book-spell-text.webp"}},{id:"orrery",name:{nl:"Het Zonnestelsel",en:"The Solar System"},rect:{x:436,y:126,w:100,h:56},walkTo:{x:404,y:282},look:e=>e.flags.gotEclipseSpell?{nl:"Het koperen zonnestelsel rust weer; de ringen staan op één lijn. De zonsverduistering-spreuk staat in je toverboek.",en:"The brass solar system rests again; its rings stand aligned. The eclipse spell is in your spellbook."}:{nl:"Een prachtig koperen zonnestelsel draait langzaam op de sokkel: een gloeiende zon met ringen van planeten en sterren eromheen. Er zit een draaimechaniek in...",en:"A beautiful brass solar system slowly turns on the pedestal: a glowing sun with rings of planets and stars around it. There is a turning mechanism inside..."},eclipsePuzzle:{requiresFlag:"wizardTripping",blockedText:{nl:"“Blijf van mijn instrumenten af!” snauwt de tovenaar zonder zelfs op te kijken. Zolang hij erbij is, mag je nergens aankomen. (De raaf fluistert: “Krra... gloeizwammen, bij de put!”)",en:"“Keep your hands off my instruments!” snaps the wizard without even looking up. While he is around you may touch nothing. (The raven whispers: “Caw... glow-caps, by the well!”)"},positions:12,moves:[[1,0,1],[1,1,1],[0,1,1]],title:{nl:"De Hemelschijf",en:"The Celestial Disc"},hint:{nl:"Zet Zon ☉, Maan ☽ en Ster ✦ alle drie bovenaan, onder de gouden wijzer. Let op: elke hendel draait meer ringen tegelijk! Buitenste = zon + ster, middelste = alle drie, binnenste = maan + ster. Groen vinkje = goed.",en:"Bring Sun ☉, Moon ☽ and Star ✦ all to the top, under the golden pointer. Careful: each lever turns more than one ring! Outer = sun + star, middle = all three, inner = moon + star. A green check = that ring is set."},rings:[{start:11},{start:10},{start:7}],tip:{nl:"💡 De volgorde maakt niet uit, alleen het AANTAL slagen per hendel. Vanaf de beginstand: buitenste 3× ▶, middelste 2× ◀, binnenste 4× ▶!",en:"💡 The order does not matter, only the NUMBER of turns per lever. From the starting position: outer 3× ▶, middle 2× ◀, inner 4× ▶!"},setFlag:"gotEclipseSpell",give:"eclipsspell",solvedZoom:{nl:"assets/art/spell-eclipse-page.webp",en:"assets/art/spell-eclipse-page-en.webp"},solvedText:{nl:"De drie ringen klikken op één lijn — de maan schuift langzaam vóór de zon en een gloeiende corona vlamt op! Boven het zonnestelsel verschijnen tekens en zilveren letters: “Umbra Solis” — de ZONSVERDUISTERING-SPREUK schrijft zich in je toverboek! (Tik de spreuk aan in je tas om hem uit te spreken bij het grote raam.)",en:"The three rings click into one line — the moon slides slowly across the sun and a glowing corona flares! Above the solar system, signs and silver letters appear: “Umbra Solis” — the SOLAR ECLIPSE SPELL writes itself into your spellbook! (Tap the spell in your bag to cast it at the great window.)"},doneText:{nl:"Het zonnestelsel rust; de zonsverduistering-spreuk staat al in jouw toverboek.",en:"The solar system rests; the eclipse spell is already in your spellbook."}}},{id:"telescope",name:{nl:"De Telescoop",en:"The Telescope"},rect:{x:382,y:94,w:58,h:74},walkTo:{x:404,y:252},zoomImg:"assets/art/telescope-horoscope.webp",zoomRequiresFlag:"eclipseActive",zoomBlockedText:{nl:"Je tuurt door de koperen telescoop, maar het felle daglicht verblindt alles — geen ster te zien. Alleen als de zon zou doven, zouden de sterren zich overdag tonen...",en:"You peer through the brass telescope, but the bright daylight blinds everything — not a star in sight. Only if the sun went dark would the stars show themselves by day..."},setFlag:"sawStars",look:{nl:"Een prachtige koperen telescoop, gericht op de hemel boven het grote raam. Op de koperen buis is een kleine raaf gegraveerd.",en:"A beautiful brass telescope, aimed at the sky above the great window. A little raven is engraved on the brass tube."}},{id:"altar",name:{nl:"Het Sterren-Altaar",en:"The Star Altar"},rect:{x:418,y:186,w:114,h:90},walkTo:{x:404,y:282},look:e=>e.flags.altarSolved?{nl:"Het altaar rust weer. De drie sterren-tekens gloeien zachtjes na in het steen.",en:"The altar rests again. The three star signs glow faintly in the stone."}:{nl:"Op het altaar ligt een rond stenen DEURZEGEL: drie draaibare schijven vol sterren-tekens rond een blauwe steen, met een hendel ernaast. Bovenaan is een gouden wijzer gebeiteld — welke drie tekens moeten daar samen onder staan?",en:"On the altar lies a round stone DOOR SEAL: three turnable discs full of star-signs around a blue stone, with a lever beside it. A golden pointer is chiselled at the top — which three signs should sit beneath it together?"},discPuzzle:{imgBase:"assets/art/seal-base.webp",title:{nl:"Het Deurzegel",en:"The Door Seal"},signs:["☉","♂","Ψ","☽","✦","♄","☿","⚹","♃","♀","✶","♆"],code:["Ψ","♃","♄"],ringShift:[0,4,8],rings:[{start:5},{start:9},{start:3}],hint:{nl:"Drie draaibare schijven vol sterren-tekens. Tik links of rechts van de buitenste, middelste of binnenste schijf om hem te draaien, tot de juiste COMBINATIE bovenaan onder de wijzer staat — en trek dan aan de HENDEL. Welke drie tekens? Kijk door de TELESCOOP wanneer de sterren overdag schijnen: het hart van de hemelschijf toont ze van boven naar beneden — 1 = buitenste, 2 = middelste, 3 = binnenste schijf!",en:"Three turnable discs full of star-signs. Tap left or right of the outer, middle or inner disc to turn it, until the right COMBINATION sits at the top under the pointer — then pull the LEVER. Which three signs? Look through the TELESCOPE while the stars shine by day: the heart of the sky-wheel shows them top to bottom — 1 = outer, 2 = middle, 3 = inner disc!"},setFlag:["altarSolved"],relight:{setFlag:"libRelit",clearFlag:"eclipseActive",delay:2600,text:{nl:"Achter het raam schuift de zwarte schijf weg van de zon. Het daglicht stroomt terug de zaal in — en in de muur, waar zojuist een boekenkast stond, gaapt nu een donkere doorgang naar beneden...",en:"Behind the window the black disc slides off the sun. Daylight floods back into the hall — and in the wall, where a bookcase stood a moment ago, a dark passage now yawns downward..."}},wrongText:{nl:"Je trekt aan de hendel... maar het zegel blijft dof. Dit is nog niet de juiste combinatie! (Hint: kijk door de telescoop tijdens de zonsverduistering — teken 1 bovenaan op de BUITENSTE schijf, teken 2 op de MIDDELSTE, teken 3 op de BINNENSTE.)",en:"You pull the lever... but the seal stays dull. Not the right combination yet! (Hint: look through the telescope during the eclipse — sign 1 on top of the OUTER disc, sign 2 on the MIDDLE, sign 3 on the INNER.)"},solvedText:{nl:"De drie tekens van de Raaf gloeien één voor één op — het DEURZEGEL vlamt goudkleurig aan! Met een diep, knarsend gerommel zwaait achter de boekenkast een GEHEIME DEUR open. Daarachter voert een trap omlaag, de duisternis in — naar de kerker...",en:"The Raven’s three signs glow one by one — the DOOR SEAL blazes golden! With a deep grinding rumble a SECRET DOOR swings open behind the bookcase. Beyond it a stair leads down, into the dark — toward the dungeon..."},doneText:{nl:"Het zegel rust; de tekens gloeien zachtjes na en de geheime deur staat open. Een trap voert omlaag, de kerker in.",en:"The seal rests; the signs glow faintly and the secret door stands open. A stair leads down, into the dungeon."}}}]},dungeon:{name:{nl:"De Kerker",en:"The Dungeon"},bg:"assets/art/scene-dungeon.webp",charFilter:"saturate(1.0) brightness(0.82) sepia(0.12) contrast(1.06)",heroShade:.7,entryText:{nl:"De wenteltrap komt uit in een klamme kerker diep onder het kasteel. Fakkels walmen aan de muren, kettingen rammelen zacht. Rechts, achter dikke ijzeren tralies, zit een magere gestalte gevangen — en er tussenin staat een reusachtige wachter, zijn hellebaard in de hand. Hij mag je niet zien.",en:"The spiral stair opens into a clammy dungeon deep beneath the castle. Torches gutter on the walls, chains rattle softly. To the right, behind thick iron bars, a thin figure is imprisoned — and between you and it stands a huge guard, halberd in hand. He must not see you."},playerStart:{x:92,y:226},spawnFrom:{library:{x:92,y:226}},depth:{far:250,near:314,sFar:1,sNear:1.4},walkable:[{x:76,y:212,w:40,h:28,notFlag:"guardPassed"},{x:44,y:212,w:104,h:40,requiresFlag:"guardPassed"},{x:36,y:246,w:444,h:66,requiresFlag:"guardPassed"}],obstacles:[{x:182,y:200,w:94,h:28},{x:276,y:196,w:70,h:28},{x:36,y:240,w:456,h:78,notFlag:"guardPassed",msg:{nl:"Je durft geen stap in de kerker te zetten — de reusachtige wachter zou je meteen zien. Alleen als je ONZICHTBAAR bent kun je verder. (De trap terug naar boven kan wel.)",en:"You dare not set a foot into the dungeon — the huge guard would spot you at once. Only while INVISIBLE can you go on. (The stair back up still works.)"}}],overlays:[],fx:{bookSparkle:{x:216,y:179,col:"255,208,110",boost:.85,noGlow:!0,sparkCount:4,staticSpark:!0,doneFlag:"gotCellKey"},nutPlant:{x:91,y:294,img:"assets/art/plant-dance.png",imgNut:"assets/art/item-bignut.webp"},waterGlint:{x:60,y:285,w:30},lockGlint:{x:418,y:165,r:9,col:"212,224,240",colOut:"200,214,235",twCol:"228,236,250",sparkCol:"245,248,255",requiresFlag:"gotCellKey",doneFlag:"fatherFreed"}},npcs:[{id:"guard",sprite:"dungeonGuard",x:322,y:246,scale:1.13,flip:!1,turnFlags:["gotCellKey","guardTurned"],sway:.015,filter:"brightness(0.82) saturate(0.96)"}],worldItems:[],hotspots:[{id:"toLibraryDungeon",name:{nl:"Terug naar boven",en:"Back Up"},rect:{x:40,y:40,w:110,h:210},walkTo:{x:92,y:228},arrow:{x:95,y:120,dir:"up"},exit:{to:"library",travelText:{nl:"Je klimt de wenteltrap weer op, terug de bibliotheek in.",en:"You climb back up the spiral stair, into the library."}}},{id:"chains",name:{nl:"De Kettingen",en:"The Chains"},rect:{x:134,y:36,w:66,h:116},walkTo:{x:162,y:252},look:{nl:"Zware roestige kettingen hangen aan de muur bij de trap. Beter om er vanaf te blijven — één tik en het galmt door de hele kerker.",en:"Heavy rusty chains hang on the wall by the stairs. Better leave them alone — one touch and the clang echoes through the whole dungeon."}},{id:"puddle",name:{nl:"Plasje Water",en:"Puddle of Water"},rect:{x:28,y:264,w:68,h:38},walkTo:{x:112,y:274},look:e=>e.flags.plantDancing?{nl:"In het plasje zwiert en huppelt het wondernoot-plantje vrolijk in het rond. De wachter kan er zijn ogen niet vanaf houden.",en:"In the puddle the wonder-nut plant sways and hops merrily. The guard cannot take his eyes off it."}:e.flags.nutInPuddle?{nl:"De wondernoot dobbert in het plasje water. Nu nog een beetje magie om hem te laten groeien... je DANS-SPREUK misschien? (Tik hem aan in je tas.)",en:"The wonder-nut bobs in the puddle. Now a little magic to make it grow... your DANCE SPELL perhaps? (Tap it in your bag.)"}:{nl:"Tussen de stenen bij de trap glinstert een ondiep plasje kwelwater. Precies genoeg water om iets kleins in te laten groeien...",en:"Between the stones by the stairs glints a shallow puddle of seep-water. Just enough water for something small to grow in..."},use:{bignut:{consume:"bignut",setFlag:"nutInPuddle",text:{nl:"PLONS! De wondernoot dobbert rond in het plasje en het groene scheutje wipt nieuwsgierig omhoog. Hij wíl groeien... maar er is magie nodig. De dans-spreuk — “laat wat stil staat vrolijk dansen”! (Tik de DANS-SPREUK aan in je tas.)",en:"SPLASH! The wonder-nut bobs about in the puddle and the little green sprout perks up curiously. It WANTS to grow... but it needs magic. The dance spell — “make what stands still dance”! (Tap the DANCE SPELL in your bag.)"}}}},{id:"guard",name:{nl:"De Wachter",en:"The Guard"},rect:{x:284,y:118,w:88,h:132},walkTo:{x:250,y:262},look:e=>e.flags.guardTurned?{nl:"De wachter staart met zijn rug naar de cel argwanend naar de trap. “Wie daar?!” gromt hij nog eens. Snel — nú de celdeur!",en:"His back to the cell, the guard peers warily at the stairs. “Who goes there?!” he growls again. Quick — the cell door, NOW!"}:e.flags.guardPassed?{nl:"De wachter tuurt met gefronste wenkbrauwen de kerker rond — jou ziet hij niet. Maar pas op: HOREN kan hij je nog wél... Maak geen geluid.",en:"The guard peers around the dungeon with a frown — he cannot see you. But beware: he can still HEAR you... Make no sound."}:{nl:"Een kolossale wachter met een hellebaard verspert de weg naar de cel. “Niemand komt bij de gevangene — niemand die ik zíe, tenminste.” Zolang hij je ziet, kom je er nooit langs... Kon je maar onzichtbaar worden. (Tik de onzichtbaarheidsspreuk aan in je tas.)",en:"A colossal guard with a halberd blocks the way to the cell. “No one reaches the prisoner — no one I can SEE, at least.” While he can see you, you will never get past... If only you could turn invisible. (Tap the invisibility spell in your bag.)"},castWith:{item:"invisspell",cutscene:"assets/art/cutscene-invisible.webp",setFlag:"guardPassed",needText:{nl:"Je hebt iets nodig om ongezien langs die wachter te komen...",en:"You need some way to get past that guard unseen..."},text:{nl:"Je fluistert de onzichtbaarheidsspreuk — “Velum Invisibilis!” — en je lichaam vervaagt tot niet meer dan een rilling in de fakkelgloed. De wachter tuurt dwars door je heen, gromt “...verbeelding” en leunt weer tegen de muur. Nu kun je ongezien langs hem naar de cel sluipen!",en:"You whisper the invisibility spell — “Velum Invisibilis!” — and your body fades to no more than a shimmer in the torchlight. The guard stares straight through you, grunts “...imagining things” and leans back against the wall. Now you can slip past him to the cell, unseen!"}}},{id:"keyTable",name:{nl:"De Sleutel op de Tafel",en:"The Key on the Table"},rect:{x:176,y:150,w:104,h:54},walkTo:{x:230,y:258},look:e=>e.flags.gotCellKey?{nl:"De tafel is leeg — de gouden celsleutel zit veilig in je tas.",en:"The table is bare — the golden cell key sits safely in your bag."}:{nl:"Op de wachttafel, naast de kaars en de fles, ligt een sleutelbos met één gouden sleutel ertussen. Dé sleutel van de cel! Maar de sleutels rinkelen bij de minste beweging...",en:"On the guard’s table, beside the candle and the bottle, lies a key ring with one golden key among the others. THE key to the cell! But the keys jingle at the slightest touch..."},keyPuzzle:{requiresFlag:"guardPassed",blockedText:{nl:"De wachter staat er met zijn neus bovenop — zolang hij je kan zien, kun je de sleutelbos onmogelijk ongemerkt pakken. Kon je maar onzichtbaar worden...",en:"The guard stands right over it — while he can see you, you could never take the key ring unnoticed. If only you could turn invisible..."},title:{nl:"De Sleutelbos — bevrijd de gouden sleutel",en:"The Key Ring — free the golden key"},hint:{nl:"De GOUDEN sleutel past op de cel — maar hij zit KLEM onder de andere sleutels! Alleen de sleutel die aan de beurt is, komt los: schuif de stippen-sleutels opzij in volgorde — eerst •, dan ••, dan ••• — en pak dán de gouden. HOUD een sleutel VAST om hem te schuiven, en laat de GELUID-meter niet vollopen: pauzeer af en toe!",en:"The GOLDEN key fits the cell — but it is STUCK beneath the other keys! Only the key whose turn it is will come loose: slide the dotted keys aside in order — • first, then ••, then ••• — and only then take the golden one. HOLD a key to slide it, and don’t let the NOISE meter fill up: pause now and then!"},keys:[{col:"donker",teeth:4,dots:2},{col:"zilver",teeth:3,dots:1},{col:"goud",teeth:3},{col:"brons",teeth:2,dots:3},{col:"donker",teeth:3}],target:2,freeOrder:[1,0,3],setFlag:"gotCellKey",give:"cellkey",failText:{nl:"“Wat was dat?!” De wachter draait met een ruk zijn hoofd — je verstijft en de sleutel zakt een stuk terug in de bos...",en:"“What was that?!” The guard snaps his head around — you freeze and the key sinks back into the ring..."},failWrongText:{nl:"RINKEL-DE-KINKEL! De hele bos danst en alle sleutels vallen terug aan de ring. Let op de STIPPEN: eerst •, dan ••, dan ••• — en pas dán de gouden!",en:"JINGLE-JANGLE! The whole ring dances and every key falls back. Watch the DOTS: • first, then ••, then ••• — and only THEN the golden one!"},solvedText:{nl:"De gouden sleutel glijdt geluidloos van de ring, recht in je onzichtbare hand. De wachter neuriet vrolijk verder — hij heeft níets gemerkt. Nu de celdeur... maar hij staat er pal naast!",en:"The golden key slides soundlessly off the ring, straight into your invisible hand. The guard hums merrily on — he noticed nothing. Now the cell door... but he stands right beside it!"},doneText:{nl:"De gouden celsleutel zit al in je tas.",en:"The golden cell key is already in your bag."}}},{id:"father",name:{nl:"De Gevangene",en:"The Prisoner"},face:"assets/art/face-father.png",rect:{x:408,y:110,w:100,h:130},walkTo:{x:408,y:268},look:e=>e.flags.fatherFreed?{nl:"De celdeur staat open. Je vader houdt je hand stevig vast — jullie zijn weer samen.",en:"The cell door stands open. Your father holds your hand tight — you are together again."}:e.flags.gotNut||e.flags.guardTurned?{nl:"Vader wacht gespannen achter de tralies. “Leid de wachter af met dat plantje, jongen — en steek dán de gouden sleutel in het slot!”",en:"Father waits tensely behind the bars. “Distract the guard with that little plant, my boy — and THEN put the golden key in the lock!”"}:e.flags.gotCellKey?{nl:"Vader kijkt naar de gouden sleutel in je onzichtbare hand en glimlacht flauwtjes. “Goed zo, jongen. Nu de wachter nog... hij mag de zwevende sleutel niet zien.”",en:"Father looks at the golden key in your invisible hand and smiles faintly. “Well done, my boy. Now the guard... he mustn’t see the floating key.”"}:{nl:"Onzichtbaar sluip je naar de tralies. De magere man kijkt op — vermoeide ogen, rood-bruin haar net als dat van jou. “...Finn?” fluistert hij. “Mijn jongen! De wachter legt zijn sleutelBOS altijd op de tafel — de GOUDEN sleutel past op deze cel. Pak hem muisstil, jongen: onzichtbaar of niet, HOREN kan hij je nog wél...”",en:"Invisible, you creep to the bars. The thin man looks up — tired eyes, red-brown hair just like yours. “...Finn?” he whispers. “My boy! The guard always leaves his key RING on the table — the GOLDEN key fits this cell. Take it quiet as a mouse, my boy: invisible or not, he can still HEAR you...”"},gift:{requiresFlag:["gotCellKey"],notFlag:"guardTurned",setFlag:"gotNut",give:["bignut"],text:{nl:"Vader kijkt naar de starende wachter en grinnikt zacht. Hij haalt iets uit zijn zak en drukt het door de tralies in je hand: een grote, glanzende WONDERNOOT met een piepklein scheutje erin. “Van de tovenaar gekregen, lang geleden. Gooi hem in dat plasje water bij de trap, spreek je DANS-SPREUK uit... en let dan maar eens op de wachter.”",en:"Father glances at the staring guard and chuckles softly. He takes something from his pocket and presses it through the bars into your hand: a big, glossy WONDER-NUT with a tiny sprout inside. “A gift from the wizard, long ago. Toss it into that puddle of water by the stairs, speak your DANCE SPELL... and then keep an eye on the guard.”"}},use:{cellkey:{requiresFlag:["guardTurned"],requiresText:{nl:"Nog niet! De wachter staart recht naar de cel — zelfs onzichtbaar zou hij de zwevende gouden sleutel zien. Vraag vader om raad: hij weet vast iets om de wachter af te leiden...",en:"Not yet! The guard stares straight at the cell — even invisible, he would see the floating golden key. Ask father for advice: he surely knows a way to distract the guard..."},consume:"cellkey",setFlag:"fatherFreed",win:!0,text:{nl:"De gouden sleutel glijdt in het glinsterende slot... KLIK. De zware celdeur zwaait piepend open en je vader stapt naar buiten. Hij tilt je op in een omhelzing die alles goedmaakt. “Mijn jongen... je hebt me gevonden én bevrijd.” Samen lopen jullie muisstil langs de wachter, de trap op, richting het daglicht — vrij!",en:"The golden key slides into the glittering lock... CLICK. The heavy cell door creaks open and your father steps out. He lifts you into a hug that makes up for everything. “My boy... you found me AND freed me.” Together you slip silently past the guard, up the stairs, toward the daylight — free!"}}}}]}}};